cd /work && cat > src/lang/types.ts <<'EOF'
export type Mode = "2d" | "3d";
export type Vec = [number, number, number];

export interface Segment {
  from: Vec;
  to: Vec;
  color: string;
  width: number;
}

export interface LogoErrorInfo {
  message: string;
  line: number;
  column: number;
}

export interface RunResult {
  segments: Segment[];
  error: LogoErrorInfo | null;
}

export class LogoError extends Error {
  line: number;
  column: number;
  constructor(message: string, line: number, column: number) {
    super(message);
    this.line = line;
    this.column = column;
  }
  info(): LogoErrorInfo {
    return { message: this.message, line: this.line, column: this.column };
  }
}

export const LIMITS = {
  chars: 50000,
  tokens: 10000,
  depth: 32,
  frames: 32,
  ops: 10000,
  segments: 10000,
  coord: 100000,
  repeat: 10000,
};
EOF
cat > src/lang/keywords.ts <<'EOF'
export type CommandId =
  | "fd" | "bk" | "rt" | "lt" | "pu" | "pd" | "color" | "width" | "repeat" | "let"
  | "if" | "ifelse" | "stop" | "home" | "cs" | "pitchup" | "pitchdown" | "rollright" | "rollleft";

const ALIASES: Record<string, string[]> = {
  fd: ["np", "naprzod", "naprzód", "fd", "forward"],
};

export const COMMANDS = new Map<string, CommandId>();
for (const [id, names] of Object.entries(ALIASES)) for (const n of names) COMMANDS.set(n, id as CommandId);

export const norm = (s: string) => s.normalize("NFC").toLowerCase();
EOF
cat > src/lang/lexer.ts <<'EOF'
import { LIMITS } from "./types";
import { norm } from "./keywords";

export type TokKind = "num" | "word" | "str" | "op" | "cmp" | "lb" | "rb" | "lp" | "rp" | "comma" | "macolon" | "nl" | "eof" | "bad";

export interface Tok {
  k: TokKind;
  /** normalised text (lowercase for words); raw text for the rest */
  text: string;
  raw: string;
  value?: number;
  line: number;
  col: number;
  /** whitespace (or line start) directly before / after the token */
  sb: boolean;
  sa: boolean;
  /** first token on its line */
  first: boolean;
  /** word written with a leading colon */
  colon?: boolean;
  msg?: string;
}

const isSpace = (c: string | undefined) => c === undefined || c === " " || c === "\t" || c === "\n" || c === "\r" || c === "\f" || c === "\v" || c === "\u00a0";
const isLetter = (c: string | undefined) => c !== undefined && /\p{L}/u.test(c);
const isDigit = (c: string | undefined) => c !== undefined && c >= "0" && c <= "9";

export function lex(source: string): Tok[] {
  const cs = Array.from(source);
  const toks: Tok[] = [];
  let i = 0;
  let line = 1;
  let col = 1;
  let lineHasTok = false;
  let counted = 0;

  const push = (t: Omit<Tok, "sb" | "sa" | "first">, startIdx: number, endIdx: number) => {
    const tok: Tok = { ...t, sb: startIdx === 0 || isSpace(cs[startIdx - 1]), sa: isSpace(cs[endIdx]), first: !lineHasTok };
    toks.push(tok);
    if (t.k !== "nl") lineHasTok = true;
    return tok;
  };
  const bad = (msg: string, l: number, c: number, s: number, e: number) => {
    push({ k: "bad", text: "", raw: "", line: l, col: c, msg }, s, e);
  };

  if (cs.length > LIMITS.chars) {
    // lex only the allowed prefix, then report the limit at the first excess char
  }
  const limit = Math.min(cs.length, LIMITS.chars);
  const advance = (n: number) => {
    for (let k = 0; k < n; k++) {
      if (cs[i] === "\n") { line++; col = 1; lineHasTok = false; } else col++;
      i++;
    }
  };

  while (i < limit) {
    const c = cs[i];
    if (c === "\n") {
      push({ k: "nl", text: "\n", raw: "\n", line, col }, i, i + 1);
      advance(1);
      continue;
    }
    if (isSpace(c)) { advance(1); continue; }
    if (c === ";") { while (i < limit && cs[i] !== "\n") advance(1); continue; }

    if (++counted > LIMITS.tokens) {
      bad(`Przekroczono limit ${LIMITS.tokens} tokenów.`, line, col, i, i + 1);
      return finish();
    }
    const s = i, sl = line, sc = col;

    if (isDigit(c) || (c === "." && isDigit(cs[i + 1]))) {
      let j = i;
      while (isDigit(cs[j])) j++;
      if (cs[j] === "." && isDigit(cs[j + 1])) { j++; while (isDigit(cs[j])) j++; }
      if (isLetter(cs[j]) || isDigit(cs[j]) || cs[j] === "_" || cs[j] === ".") {
        let e = j;
        while (isLetter(cs[e]) || isDigit(cs[e]) || cs[e] === "_" || cs[e] === ".") e++;
        const txt = cs.slice(s, e).join("");
        bad(`Niepoprawna liczba „${txt}”. Liczby to zwykłe zapisy dziesiętne, np. 80, 12.5 lub .5.`, sl, sc, s, e);
        return finish();
      }
      const raw = cs.slice(s, j).join("");
      advance(j - i);
      push({ k: "num", text: raw, raw, value: Number(raw), line: sl, col: sc }, s, j);
      continue;
    }

    if (isLetter(c) || c === "_" || (c === ":" && (isLetter(cs[i + 1]) || cs[i + 1] === "_"))) {
      const colon = c === ":";
      let j = colon ? i + 1 : i;
      const start = j;
      while (isLetter(cs[j]) || isDigit(cs[j]) || cs[j] === "_") j++;
      const raw = cs.slice(start, j).join("");
      const text = norm(raw);
      if (!colon && text === "ma" && cs[j] === ":") {
        advance(j + 1 - i);
        push({ k: "macolon", text: "ma:", raw: "ma:", line: sl, col: sc }, s, j + 1);
        continue;
      }
      advance(j - i);
      push({ k: "word", text, raw: colon ? ":" + raw : raw, line: sl, col: sc, colon }, s, j);
      continue;
    }

    if (c === '"') {
      let j = i + 1;
      while (j < cs.length && cs[j] !== '"' && cs[j] !== "\n") j++;
      if (cs[j] !== '"') {
        bad("Niedomknięty napis: brakuje zamykającego cudzysłowu.", sl, sc, s, j);
        return finish();
      }
      const raw = cs.slice(s, j + 1).join("");
      advance(j + 1 - i);
      push({ k: "str", text: raw.slice(1, -1), raw, line: sl, col: sc }, s, j + 1);
      continue;
    }

    if (c === "<" || c === ">" || c === "=") {
      let op = c;
      if (c === "<" && (cs[i + 1] === "=" || cs[i + 1] === ">")) op = c + cs[i + 1];
      else if (c === ">" && cs[i + 1] === "=") op = ">=";
      advance(op.length);
      push({ k: "cmp", text: op, raw: op, line: sl, col: sc }, s, s + op.length);
      continue;
    }
    const single: Record<string, TokKind> = { "+": "op", "-": "op", "*": "op", "/": "op", "[": "lb", "]": "rb", "(": "lp", ")": "rp", ",": "comma" };
    if (single[c]) {
      advance(1);
      push({ k: single[c], text: c, raw: c, line: sl, col: sc }, s, s + 1);
      continue;
    }
    bad(`Nieznany znak „${c}”.`, sl, sc, s, s + 1);
    return finish();
  }

  if (cs.length > LIMITS.chars) {
    bad(`Program jest za długi: limit to ${LIMITS.chars} znaków.`, line, col, i, i + 1);
    return finish();
  }
  return finish();

  function finish(): Tok[] {
    toks.push({ k: "eof", text: "", raw: "", line, col, sb: true, sa: true, first: !lineHasTok });
    return toks;
  }
}
EOF
cat > src/lang/ast.ts <<'EOF'
import type { CommandId } from "./keywords";

export interface Pos { line: number; col: number }

export type Expr =
  | { k: "num"; v: number; pos: Pos }
  | { k: "var"; name: string; pos: Pos }
  | { k: "rep"; pos: Pos }
  | { k: "un"; op: "+" | "-"; e: Expr; pos: Pos }
  | { k: "bin"; op: "+" | "-" | "*" | "/"; l: Expr; r: Expr; pos: Pos };

export type Stmt = { pos: Pos } & (
  | { t: "cmd"; id: CommandId; arg: Expr | null }
);

export interface Program {
  body: Stmt[];
}
EOF
cat > src/lang/parser.ts <<'EOF'
import { lex, type Tok } from "./lexer";
import { COMMANDS } from "./keywords";
import { LogoError, type Mode } from "./types";
import type { Expr, Program, Stmt } from "./ast";

export function parse(source: string, _mode: Mode): Program {
  const toks = lex(source).filter((t) => t.k !== "nl");
  let p = 0;
  const peek = () => toks[p];
  const next = () => toks[p++];
  const fail = (msg: string, t: Tok): never => {
    throw new LogoError(msg, t.line, t.col);
  };
  const checkBad = (t: Tok) => { if (t.k === "bad") fail(t.msg!, t); };

  function expr(): Expr {
    const t = next();
    checkBad(t);
    if (t.k === "num") return { k: "num", v: t.value!, pos: { line: t.line, col: t.col } };
    return fail("Oczekiwano liczby.", t);
  }

