import type { Program } from "./ast";
import type { Segment } from "./types";

export function execute(program: Program): Segment[] {
  const segments: Segment[] = [];
  let y = 0;
  for (const s of program.body) {
    if (s.arg && s.arg.k === "num") {
      segments.push({ from: [0, y, 0], to: [0, y + s.arg.v, 0], color: "#16866a", width: 3 });
      y += s.arg.v;
    }
  }
  return segments;
}
