import { execute } from "./interpreter";
import { LogoError, type Mode, type RunResult } from "./types";

export function run(source: string, mode: Mode): RunResult {
  try {
    const program = parse(source, mode);
    return { segments: execute(program), error: null };
  } catch (e) {
    if (e instanceof LogoError) return { segments: [], error: e.info() };
    throw e;
  }
}
