import type { Expr, Program, Stmt } from "./ast";
import { LogoError, type Segment, type Vec } from "./types";

const dot = (a: Vec, b: Vec) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

/** sin/cos in degrees, exact for multiples of 90 so right angles do not drift */
function sincos(deg: number): [number, number] {
  const m = ((deg % 360) + 360) % 360;
  if (m === 0) return [0, 1];
  if (m === 90) return [1, 0];
  if (m === 180) return [0, -1];
  if (m === 270) return [-1, 0];
  const r = (deg * Math.PI) / 180;
  return [Math.sin(r), Math.cos(r)];
}

/** rotate (a, b) in their plane: a' = a cos + b sin, b' = b cos - a sin */
function rotate(a: Vec, b: Vec, deg: number): [Vec, Vec] {
  const [s, c] = sincos(deg);
  return [
    [a[0] * c + b[0] * s + 0, a[1] * c + b[1] * s + 0, a[2] * c + b[2] * s + 0],
    [b[0] * c - a[0] * s + 0, b[1] * c - a[1] * s + 0, b[2] * c - a[2] * s + 0],
  ];
}

export class Machine {
  segments: Segment[] = [];
  pos: Vec = [0, 0, 0];
  heading: Vec = [0, 1, 0];
  right: Vec = [1, 0, 0];
  up: Vec = [0, 0, 1];
  penDown = true;
  color = "#16866a";
  width = 3;

  constructor(private program: Program) {}

  /** Executes the program; yields after every executed operation. */
  *steps(): Generator<{ line: number; col: number }, void, void> {
    for (const s of this.program.body) {
      this.exec(s);
      yield { line: s.pos.line, col: s.pos.col };
    }
  }

  private evalExpr(e: Expr): number {
    if (e.k === "num") return e.v;
    throw new LogoError("Nieobsługiwane wyrażenie.", e.pos.line, e.pos.col);
  }

  private exec(s: Stmt) {
    const n = this.evalExpr(s.arg!);
    switch (s.id) {
      case "fd": this.move(n); break;
      case "bk": this.move(-n); break;
      case "rt": [this.heading, this.right] = rotate(this.heading, this.right, n); break;
      case "lt": [this.heading, this.right] = rotate(this.heading, this.right, -n); break;
    }
  }

  private move(d: number) {
    const to: Vec = [
      this.pos[0] + this.heading[0] * d + 0,
      this.pos[1] + this.heading[1] * d + 0,
      this.pos[2] + this.heading[2] * d + 0,
    ];
    if (this.penDown && (to[0] !== this.pos[0] || to[1] !== this.pos[1] || to[2] !== this.pos[2])) {
      this.segments.push({ from: this.pos, to, color: this.color, width: this.width });
    }
    this.pos = to;
  }
}

export function execute(program: Program): Segment[] {
  const m = new Machine(program);
  for (const _ of m.steps());
  return m.segments;
}
