  const next = () => toks[p++];
  const fail = (msg: string, t: Tok): never => {
    throw new LogoError(msg, t.line, t.col);
  };
  const checkBad = (t: Tok) => { if (t.k === "bad") fail(t.msg!, t); };

  /** the token where a missing argument is reported: the one found, or the command at end of program */
  const missing = (cmd: Tok, what: string): never => {
    const t = peek();
    checkBad(t);
    return fail(`Brakuje argumentu: ${what}.`, t.k === "eof" ? cmd : t);
  };

  function expr(cmd: Tok): Expr {
    const t = peek();
    checkBad(t);
    if (t.k === "num") { next(); return { k: "num", v: t.value!, pos: { line: t.line, col: t.col } }; }
    return missing(cmd, "oczekiwano liczby");
  }

  /** literal (name-free) expressions are validated now; others when executed */
  function literalInt(e: Expr, lo: number, hi: number, what: string) {
    if (!isConstant(e)) return;
    let v: number;
    try { v = evalExpr(e, constCtx); } catch (x) {
      if (x instanceof EvalFail) return fail(x.message, { line: e.pos.line, col: e.pos.col } as Tok);
      throw x;
    }
    if (!Number.isInteger(v) || v < lo || v > hi) fail(`${what} musi być liczbą całkowitą od ${lo} do ${hi}.`, { line: e.pos.line, col: e.pos.col } as Tok);
  }

  const body: Stmt[] = [];
  while (peek().k !== "eof") {
    const t = next();
    checkBad(t);
    const id = t.k === "word" ? COMMANDS.get(t.text) : undefined;
    if (!id) fail(`Nieznane polecenie „${t.raw}”.`, t);
    const pos = { line: t.line, col: t.col };
    const kind = ARG_KIND[id!];
    if (kind === "none") body.push({ t: "cmd", id: id!, arg: null, pos });
    else if (kind === "color") {
      const a = peek();
      checkBad(a);
      if (a.k !== "str") missing(t, "oczekiwano koloru w cudzysłowie, np. \"#16866a\"");
      next();
