cat >> tests/interpreter.test.ts <<'EOF'

const dist = (src: string) => {
  const r = run(src, "2d");
  expect(r.error).toBeNull();
  return r.segments[0].to[1];
};

describe("run: expressions", () => {
  test("* and / bind tighter than + and -", () => {
    expect(dist("np 2 + 3 * 4")).toBe(14);
    expect(dist("np 20 / 4 + 1")).toBe(6);
  });
  test("equal precedence associates to the left", () => {
    expect(dist("np 20 - 5 - 3")).toBe(12);
    expect(dist("np 100 / 5 / 2")).toBe(10);
  });
  test("parentheses group", () => {
    expect(dist("np (2 + 3) * 4")).toBe(20);
  });
  test("a binary operator needs whitespace on both sides or on neither", () => {
    expect(dist("np 10 - 5")).toBe(5);
    expect(dist("np 10-5")).toBe(5);
    expect(dist("np 10*2")).toBe(20);
  });
  test("`np 10 -5` is np 10 followed by a stray token, reported at the minus", () => {
    const r = run("np 10 -5", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 1, column: 7 });
    expect(run("np 10- 5", "2d").error).toMatchObject({ line: 1, column: 6 });
    expect(run("np 10 *5", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("unary signs stack and apply to any operand", () => {
    expect(dist("np -(3 - 5)")).toBe(2);
    expect(dist("np - -2")).toBe(2);
    expect(dist("np +3")).toBe(3);
    expect(dist("np 10 - -2")).toBe(12);
    expect(dist("np -(-(-4))")).toBe(-4);
  });
  test("decimal literals: 12.5 and .5", () => {
    expect(dist("np 12.5 + .5")).toBe(13);
  });
  test("other number spellings are errors", () => {
    for (const bad of ["1e3", "0x10", "NaN", "Infinity", "5.", "1.2.3"]) {
      expect(run(`np ${bad}`, "2d").error, bad).not.toBeNull();
    }
    expect(run("np 1e3", "2d").error).toMatchObject({ line: 1, column: 4 });
  });
  test("missing argument is reported where it should have started", () => {
    expect(run("np", "2d").error).toMatchObject({ line: 1, column: 1 });
    expect(run("np\npw 90", "2d").error).toMatchObject({ line: 2, column: 1 });
    expect(run("np (", "2d").error).toMatchObject({ line: 1, column: 4 });
    expect(run("np 3 +", "2d").error).toMatchObject({ line: 1, column: 1 });
  });
  test("unbalanced parentheses are errors", () => {
    expect(run("np (3 + 4", "2d").error).not.toBeNull();
    expect(run("np 3 + 4)", "2d").error).toMatchObject({ line: 1, column: 9 });
  });
  test("division by zero is a run-time error at the argument; earlier drawing is kept", () => {
    const r = run("np 10\nnp 5 / (3 - 3)", "2d");
    expect(r.segments).toEqual([seg([0, 0, 0], [0, 10, 0])]);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("a non-finite result is a run-time error", () => {
    const big = "9".repeat(200);
    const r = run(`np 1\nnp ${big} * ${big} * ${big} * ${big}`, "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
});
