cat >> tests/interpreter.test.ts <<'EOF'

describe("run: repeat", () => {
  test("powtorz runs the body n times, nested bodies allowed", () => {
    expect(run("powtorz 4 [np 10 pw 90]", "2d").segments).toHaveLength(4);
    expect(run("REPEAT 3 [powtórz 2 [np 1]]", "2d").segments).toHaveLength(6);
  });
  test("a count of 0 runs nothing", () => {
    expect(run("powtorz 0 [np 10]", "2d")).toEqual({ segments: [], error: null });
  });
  test("nrpowt counts iterations from 1 and refers to the innermost repeat", () => {
    const r = run("powtorz 3 [np nrpowt]", "2d");
    expect(r.segments.map((s) => s.to[1])).toEqual([1, 3, 6]);
    const n = run("powtorz 2 [powtorz 3 [np repcount] ws 100]", "2d");
    expect(n.segments.map((s) => s.to[1] - s.from[1])).toEqual([1, 2, 3, -100, 1, 2, 3, -100].filter((v) => v > 0));
  });
  test("the repeat count may use the enclosing counter", () => {
    expect(run("powtorz 3 [powtorz nrpowt [np 1]]", "2d").segments).toHaveLength(6);
  });
  test("nrpowt outside a repeat is a parse-time error at the word", () => {
    const r = run("np 5\nnp nrpowt", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
    expect(run("powtorz nrpowt [np 1]", "2d").error).toMatchObject({ line: 1, column: 9 });
  });
  test("literal counts outside 0-10000 or non-integer are parse-time errors at the count", () => {
    for (const bad of ["10001", "2.5", "-1"]) {
      const r = run(`np 1\npowtorz ${bad} [np 1]`, "2d");
      expect(r.segments, bad).toEqual([]);
      expect(r.error, bad).toMatchObject({ line: 2, column: 9 });
    }
  });
  test("brackets must balance; errors point at the offending bracket", () => {
    expect(run("powtorz 2 [np 1", "2d").error).toMatchObject({ line: 1, column: 11 });
    expect(run("np 1 ]", "2d").error).toMatchObject({ line: 1, column: 6 });
    expect(run("powtorz 2 np 1", "2d").error).toMatchObject({ line: 1, column: 11 });
    expect(run("powtorz 2", "2d").error).toMatchObject({ line: 1, column: 1 });
  });
  test("stop at top level ends the program", () => {
    expect(run("np 1 stop np 1", "2d").segments).toHaveLength(1);
    expect(run("powtorz 5 [np 1 stop]", "2d").segments).toHaveLength(1);
  });
});
EOF
