function statement(): Stmt {
  const t = next();
  checkBad(t);
  const id = t.k === "word" ? COMMANDS.get(t.text) : undefined;
  if (!id) strayError(t);
  const pos = { line: t.line, col: t.col };
  const kind = ARG_KIND[id!];
  if (kind === "none") return { t: "cmd", id: id!, arg: null, pos };
  if (kind === "repeat") {
    const count = expr(t);
    literalInt(count, 0, 10000, "Liczba powtórzeń");
    const open = openBracket(t);
    repDepth++;
    const body = block(open);
    repDepth--;
    return { t: "repeat", count, body, pos };
