cat >> tests/interpreter.test.ts <<'EOF'

describe("run: variables", () => {
  test("niech assigns, names ignore case and accept the :name form", () => {
    expect(dist("niech Bok 40 np :bok + BOK")).toBe(80);
    expect(dist("let x 3 niech x x * 2 np x")).toBe(6);
  });
  test("a name used but never assigned anywhere is a parse-time error at the name", () => {
    const r = run("np 5\nnp ile", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
  });
  test("a variable assigned later at top level may be named earlier; reading it unassigned is a run-time error at the argument start", () => {
    const r = run("np 5\nnp 10 + x\nniech x 1", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 4 });
    expect(r.error!.message).toContain("x");
  });
  test("a variable may be read in a loop before a later assignment on the same path ends the error", () => {
    expect(run("powtorz 2 [niech x 1 np x]", "2d").error).toBeNull();
  });
  test("variable names may not be command words", () => {
    expect(run("niech np 5", "2d").error).toMatchObject({ line: 1, column: 7 });
    expect(run("niech nrpowt 5", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("niech needs a name and a value", () => {
    expect(run("niech", "2d").error).toMatchObject({ line: 1, column: 1 });
    expect(run("niech x", "2d").error).toMatchObject({ line: 1, column: 1 });
    expect(run("niech 5 5", "2d").error).toMatchObject({ line: 1, column: 7 });
  });
  test("an invalid assigned expression is reported at its first token", () => {
    const r = run("np 1\nniech x 4 / 0", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 2, column: 9 });
  });
});
EOF
