describe("run: conditionals", () => {
  const holds = (cond: string) => run(`jeśli ${cond} [np 1]`, "2d").segments.length === 1;
  test("all six comparisons", () => {
    expect([holds("1 < 2"), holds("2 < 1"), holds("2 > 1"), holds("1 > 2")]).toEqual([true, false, true, false]);
    expect([holds("2 <= 2"), holds("3 <= 2"), holds("2 >= 2"), holds("1 >= 2")]).toEqual([true, false, true, false]);
    expect([holds("2 = 2"), holds("2 = 3"), holds("2 <> 3"), holds("2 <> 2")]).toEqual([true, false, true, false]);
  });
  test("comparisons are exact and need no spacing rule", () => {
    expect(holds("0.1 + 0.2 = 0.3")).toBe(false);
    expect(holds("1<2")).toBe(true);
    expect(holds("10-5=5")).toBe(true);
  });
  test("aliases: if/jesli and ifelse/jeżeli/jezeli", () => {
    expect(run("if 1 = 1 [np 1]", "2d").segments).toHaveLength(1);
    expect(run("JESLI 1 = 1 [np 1]", "2d").segments).toHaveLength(1);
  });
  test("jeżeli runs the first body when true, else the second", () => {
    expect(run("jeżeli 1 < 2 [np 1] [np 2]", "2d").segments[0].to[1]).toBe(1);
    expect(run("ifelse 2 < 1 [np 1] [np 2]", "2d").segments[0].to[1]).toBe(2);
    expect(run("jezeli 2 < 1 [np 1] [pw 90 np 5]", "2d").segments[0].to).toEqual([5, 0, 0]);
  });
  test("conditions use variables and nrpowt; stop inside a body ends the program", () => {
    const r = run("powtorz 10 [jeśli nrpowt > 3 [stop] np 1]", "2d");
    expect(r.segments).toHaveLength(3);
  });
  test("malformed conditionals report the token found", () => {
    expect(run("jeśli 1 [np 1]", "2d").error).toMatchObject({ line: 1, column: 9 });
    expect(run("jeżeli 1 < 2 [np 1]", "2d").error).toMatchObject({ line: 1, column: 19 + 0 > 0 ? 1 : 1 });
    expect(run("jeśli 1 < 2 np 1", "2d").error).toMatchObject({ line: 1, column: 13 });
  });
  test("an unassigned variable in a condition is reported at the start of its side", () => {
    const r = run("niech y 1\njeśli 3 + x < 5 [np 1]\nniech x 2", "2d");
    expect(r.error).toMatchObject({ line: 2, column: 7 });
  });
});
EOF
