cat >> tests/interpreter.test.ts <<'EOF'

describe("run: procedures", () => {
  const sq = "oto kwadrat ma: bok, kąt\n  powtorz 4 [np bok pw kąt]\njuż\n";
  test("define with ma: and call with positional expression arguments", () => {
    const r = run(sq + "kwadrat 40 * 2 90", "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to)).toEqual([[0, 80, 0], [80, 80, 0], [80, 0, 0], [0, 0, 0]]);
  });
  test("definitions may follow their calls; juz/end and to are aliases; case is ignored", () => {
    const r = run("KWADRAT 10 90\nTO Kwadrat ma: Bok, Kat\n powtorz 4 [np BOK pw kat]\nEND\n", "2d");
    expect(r.error).toBeNull();
    expect(r.segments).toHaveLength(4);
  });
  test("legacy header and :name references", () => {
    const r = run("oto kw :bok :kąt\n powtorz 4 [np :bok pw kąt]\njuż\nkw 10 90", "2d");
    expect(r.error).toBeNull();
    expect(r.segments).toHaveLength(4);
  });
  test("a procedure without parameters", () => {
    expect(run("oto linia\n np 7\nużj\nlinia", "2d").error).not.toBeNull();
    expect(run("oto linia\n np 7\njuz\nlinia linia", "2d").segments).toHaveLength(2);
  });
  test("recursion with stop ends the procedure, not just the repeat or conditional body", () => {
    const src = "oto odl ma: n\n jeśli n < 1 [stop]\n np n\n odl n - 1\njuż\nodl 3";
    const r = run(src, "2d");
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1] - s.from[1])).toEqual([3, 2, 1]);
    const r2 = run("oto f\n powtorz 5 [np 1 stop]\n np 100\njuż\nf np 2", "2d");
    expect(r2.segments.map((s) => s.to[1] - s.from[1])).toEqual([1, 2]);
  });
  test("niech inside a procedure is local and shadows a global for the call", () => {
    const src = "niech x 5\noto f\n niech x 1\n np x\njuż\nf\nnp x";
    const r = run(src, "2d");
    expect(r.segments.map((s) => s.to[1] - s.from[1])).toEqual([1, 5]);
  });
  test("a procedure reads globals and parameters can be reassigned", () => {
    const src = "niech g 4\noto f ma: p\n niech p p + g\n np p\njuż\nf 1";
    expect(run(src, "2d").segments[0].to[1]).toBe(5);
  });
  test("locals are discarded between calls", () => {
    const src = "oto f\n jeśli nrpowt2 = 0 [np 1]\njuż";
    expect(run(src, "2d").error).not.toBeNull();
    const src2 = "oto f ma: a\n jeśli a = 0 [niech t 1]\n np t\njuż\nf 0\nf 1";
    const r = run(src2, "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 3, column: 5 });
  });
  test("a parameter may share its name with a procedure: call in command position, parameter in argument position", () => {
    const src = "oto bok ma: bok\n np bok\njuż\nbok 6";
    expect(run(src, "2d").segments[0].to[1]).toBe(6);
  });
  test("a variable may not be named like a procedure", () => {
    expect(run("oto f\n np 1\njuż\nniech f 5", "2d").error).toMatchObject({ line: 4, column: 7 });
  });
  test("nrpowt in a procedure body outside a repeat is a parse-time error even if called from a repeat", () => {
    const r = run("oto f\n np nrpowt\njuż\npowtorz 2 [f]", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 5 });
    expect(run("oto f\n powtorz 2 [np nrpowt]\njuż\nf", "2d").error).toBeNull();
  });
  test("wrong argument counts", () => {
    expect(run(sq + "kwadrat 40\nnp 1", "2d").error).toMatchObject({ line: 5, column: 1 });
    expect(run(sq + "kwadrat 40", "2d").error).toMatchObject({ line: 4, column: 1 });
    expect(run(sq + "kwadrat 40 90 5", "2d").error).toMatchObject({ line: 4, column: 15 });
    expect(run(sq + "kwadrat", "2d").error).toMatchObject({ line: 4, column: 1 });
  });
  test("definitions are top-level only, once, and must end with już", () => {
    expect(run("powtorz 2 [\noto f\njuż\n]", "2d").error).toMatchObject({ line: 2, column: 1 });
    expect(run("oto a\n oto b\n już\njuż", "2d").error).toMatchObject({ line: 2, column: 2 });
    expect(run("oto a\njuż\noto A\njuż", "2d").error).toMatchObject({ line: 3, column: 5 });
    expect(run("np 1\n\noto a\n np 1\n", "2d").error).toMatchObject({ line: 3, column: 1 });
    expect(run("np 1 oto a\njuż", "2d").error).toMatchObject({ line: 1, column: 6 });
    expect(run("już", "2d").error).toMatchObject({ line: 1, column: 1 });
    expect(run("oto a\n np 1 już\n", "2d").error).not.toBeNull();
  });
  test("header problems: command-word names, duplicate and keyword parameters", () => {
    expect(run("oto np\njuż", "2d").error).toMatchObject({ line: 1, column: 5 });
    expect(run("oto f ma: a, a\njuż", "2d").error).toMatchObject({ line: 1, column: 14 });
    expect(run("oto f ma: pw\njuż", "2d").error).toMatchObject({ line: 1, column: 11 });
  });
  test("names from another procedure are not visible", () => {
    const src = "oto a\n niech loc 1\njuż\noto b\n np loc\njuż\nb";
    expect(run(src, "2d").error).toMatchObject({ line: 5, column: 5 });
  });
});
EOF
