describe("run: 3D orientation", () => {
  const end = (src: string) => {
    const r = run(src, "3d");
    expect(r.error).toBeNull();
    return r.segments[r.segments.length - 1].to;
  };
  test("gora tips the nose towards up; dol the other way", () => {
    expect(end("gora 90 np 10")).toEqual([0, 0, 10]);
    expect(end("dol 90 np 10")).toEqual([0, 0, -10]);
    expect(end("gora 90 dol 90 np 10")).toEqual([0, 10, 0]);
  });
  test("pp rolls: up becomes the former right, right the former down; heading is unchanged", () => {
    expect(end("pp 90 np 10")).toEqual([0, 10, 0]);
    expect(end("pp 90 gora 90 np 10")).toEqual([10, 0, 0]);
    expect(end("pp 90 pw 90 np 10")).toEqual([0, 0, -10]);
    expect(end("pl 90 gora 90 np 10")).toEqual([-10, 0, 0]);
    expect(end("przechylprawo 90 przechyllewo 90 gora 90 np 1")).toEqual([0, 0, 1]);
    expect(end("rollright 90 rollleft 90 pitchup 90 fd 1")).toEqual([0, 0, 1]);
  });
  test("a tilted circle really leaves the plane (Pierścień: 30 degrees)", () => {
    const r = run("gora 30 powtorz 36 [np 12 pw 10]", "3d");
    const zs = r.segments.map((s) => s.to[2]);
    expect(Math.max(...zs)).toBeGreaterThan(20);
  });
  test("pitch and roll are parse-time errors at the command in 2D, even if never executed", () => {
    for (const c of ["gora 5", "dol 5", "pp 5", "pl 5", "pitchup 5", "rr 5"]) {
      const r = run(`np 5\npowtorz 0 [${c}]`, "2d");
      expect(r.segments, c).toEqual([]);
      expect(r.error, c).toMatchObject({ line: 2, column: 12 });
    }
  });
  test("flat programs give identical coordinates in both modes", () => {
    const src = "powtorz 12 [powtorz 4 [np 100 pw 90] pw 30]";
    expect(run(src, "3d")).toEqual(run(src, "2d"));
    expect(run(src, "2d").segments.every((s) => s.from[2] === 0 && s.to[2] === 0)).toBe(true);
  });
});
EOF
