describe("run: limits", () => {
  const nest = (n: number, open: string, inner: string) => open.repeat(n) + inner + "]".repeat(n);
  test("source longer than 50,000 characters is an error and draws nothing", () => {
    const ok = "np 1\n; " + "x".repeat(49000);
    expect(run(ok, "2d").error).toBeNull();
    const r = run("np 1\n; " + "x".repeat(50000), "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).not.toBeNull();
  });
  test("10,000 tokens are allowed, the 10,001st is an error at that token", () => {
    expect(run("pu\n".repeat(10000), "2d").error).toBeNull();
    const r = run("np 1\n".repeat(5000), "2d");
    expect(r.error).toMatchObject({ message: expect.stringContaining("10000") });
    expect(r.segments).toEqual([]);
    expect(r.error!.line).toBe(5000);
    expect(r.error!.column).toBe(1);
    expect(run("np 1\n".repeat(5001), "2d").error).toMatchObject({ line: 5001, column: 1 });
  });
  test("brackets nest 32 deep, not 33 (conditionals count too)", () => {
    expect(run(nest(32, "powtorz 0 [", ""), "2d").error).toBeNull();
    expect(run(nest(33, "powtorz 0 [", ""), "2d").error).toMatchObject({ line: 1, column: 32 * 11 + 10 });
    expect(run(nest(32, "jeśli 1 = 2 [", ""), "2d").error).toBeNull();
    expect(run(nest(33, "jeśli 1 = 2 [", ""), "2d").error).not.toBeNull();
  });
  test("32 active frames: recursion deeper than 32 stops with the drawing kept", () => {
    const r = run("oto f\n np 1\n f\njuż\nf", "2d");
    expect(r.segments).toHaveLength(32);
    expect(r.error).toMatchObject({ line: 3, column: 2 });
  });
  test("repeat and call frames count together; conditional bodies do not", () => {
    const deep = (reps: number) => `oto f\n ${"powtorz 1 [".repeat(reps)}pu${"]".repeat(reps)}\njuż\nf`;
    expect(run(deep(31), "2d").error).toBeNull();
    expect(run(deep(32), "2d").error).not.toBeNull();
    const cond = `oto f\n ${"jeśli 1 = 1 [".repeat(32)}pu${"]".repeat(32)}\njuż\nf`;
    expect(run(cond, "2d").error).toBeNull();
  });
  test("10,000 executed operations: repeat = 1 + 2 per iteration for one command", () => {
    expect(run("powtorz 4999 [pu]", "2d").error).toBeNull();
    const r = run("powtorz 5000 [np 1]", "2d");
    expect(r.segments).toHaveLength(5000);
    expect(r.error).toMatchObject({ line: 1, column: 1 });
  });
  test("each conditional, its body finish and each call count as operations", () => {
    expect(run("powtorz 2499 [jeśli 1 = 1 [pu]]", "2d").error).toBeNull();
    expect(run("powtorz 2500 [jeśli 1 = 1 [pu]]", "2d").error).not.toBeNull();
    expect(run("oto f\n pu\njuż\npowtorz 2499 [f]", "2d").error).toBeNull();
    expect(run("oto f\n pu\njuż\npowtorz 2500 [f]", "2d").error).not.toBeNull();
    expect(run("powtorz 2499 [niech a 1 pu]", "2d").error).toBeNull();
  });
  test("reaching the end of the program is not an operation; evaluating expressions is free", () => {
    expect(run("powtorz 4999 [np 1 + 1 + 1 + 1 + 1 + 1]", "2d").error).not.toBeNull(); // 1 + 2*4999 = 9999 fits, but see below
  });
  test("coordinates stay within ±100,000", () => {
    expect(run("np 100000", "2d").error).toBeNull();
    const r = run("np 60000 np 60000", "2d");
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 1, column: 10 });
    expect(run("pod np 100001", "2d").error).not.toBeNull();
    expect(run("gora 90 np 100001", "3d").error).not.toBeNull();
  });
});
EOF
