/** returns true when `stop` ended the block */
private *block(stmts: Stmt[]): Generator<{ line: number; col: number }, boolean, void> {
  for (const s of stmts) {
    if (s.t === "repeat") {
      const n = this.evalArg(s.count);
      if (!Number.isInteger(n) || n < 0 || n > 10000) {
        throw new LogoError("Liczba powtórzeń musi być liczbą całkowitą od 0 do 10000.", s.count.pos.line, s.count.pos.col);
      }
      yield { line: s.pos.line, col: s.pos.col };
      for (let i = 1; i <= n; i++) {
        this.reps.push(i);
        const stopped = yield* this.block(s.body);
        this.reps.pop();
        if (stopped) return true;
      }
      continue;
    }
    if (s.t === "call") {
      const proc = this.program.procs.get(s.name)!;
      const vars = new Map<string, number>();
      s.args.forEach((a, i) => vars.set(proc.params[i], this.evalArg(a)));
      yield { line: s.pos.line, col: s.pos.col };
      const saved = this.frame;
      this.frame = { vars, reps: [], top: false };
      yield* this.block(proc.body);
      this.frame = saved;
      continue;
    }
    if (s.t === "if") {
      const a = this.evalArg(s.cond.l);
      const b = this.evalArg(s.cond.r);
      const ok = { "<": a < b, ">": a > b, "=": a === b, "<=": a <= b, ">=": a >= b, "<>": a !== b }[s.cond.op];
      yield { line: s.pos.line, col: s.pos.col };
      const body = ok ? s.then : s.else;
      if (body && (yield* this.block(body))) return true;
      continue;
    }
    if (s.t === "let") {
      this.frame.vars.set(s.name, this.evalArg(s.value));
      yield { line: s.pos.line, col: s.pos.col };
      continue;
    }
    if (s.id === "stop") return true;
    this.exec(s);
    yield { line: s.pos.line, col: s.pos.col };
  }
  return false;
}

