import { test, expect, describe } from "bun:test";
import { Controller, type Scheduler } from "../src/core/controller";
import { run } from "../src/lang";
import type { Mode } from "../src/lang/types";

/** a manual clock standing in for requestAnimationFrame */
class ManualScheduler implements Scheduler {
  private cb: ((dt: number) => void) | null = null;
  request(cb: (dt: number) => void) { this.cb = cb; return 1; }
  cancel() { this.cb = null; }
  get pending() { return this.cb !== null; }
  tick(ms: number) { const cb = this.cb; this.cb = null; cb?.(ms); }
}

function make(source: string, mode: Mode = "2d") {
  const sched = new ManualScheduler();
  const cur = { source, mode };
  const c = new Controller({ source: () => cur, scheduler: sched });
  return { c, sched, cur };
}

describe("controller: stepping and reset", () => {
  test("step executes one command at a time, highlighting its line", () => {
    const { c } = make("np 10\npw 90\nnp 5");
    expect(c.snapshot().state).toBe("idle");
    c.step();
    let s = c.snapshot();
    expect(s.state).toBe("paused");
    expect(s.segments).toHaveLength(1);
    expect(s.current).toMatchObject({ line: 1 });
    c.step();
    s = c.snapshot();
    expect(s.segments).toHaveLength(1);
    expect(s.current).toMatchObject({ line: 2 });
    expect(s.turtle.heading).toEqual([1, 0, 0]);
    c.step();
    s = c.snapshot();
    expect(s.segments).toHaveLength(2);
    expect(s.state).toBe("paused");
    c.step();
    expect(c.snapshot().state).toBe("done");
    expect(c.snapshot().current).toBeNull();
  });
  test("reset forgets the drawing and puts the turtle home", () => {
    const { c } = make("np 10 pw 90 np 5");
    c.step(); c.step(); c.step();
    c.reset();
    const s = c.snapshot();
    expect(s.state).toBe("idle");
    expect(s.segments).toEqual([]);
    expect(s.turtle.pos).toEqual([0, 0, 0]);
    expect(s.turtle.heading).toEqual([0, 1, 0]);
    expect(s.current).toBeNull();
  });
  test("stepping after done starts a fresh run", () => {
    const { c } = make("np 10");
    c.step(); c.step();
    expect(c.snapshot().state).toBe("done");
    c.step();
    expect(c.snapshot().state).toBe("paused");
    expect(c.snapshot().segments).toHaveLength(1);
  });
  test("czyść during stepping empties the visible drawing", () => {
    const { c } = make("np 10\ncs\nnp 1");
    c.step(); c.step();
    expect(c.snapshot().segments).toEqual([]);
    c.step();
    expect(c.snapshot().segments).toHaveLength(1);
  });
});
EOF
