import { Machine, parse, LogoError, type LogoErrorInfo, type Mode, type Segment, type Step, type Vec } from "../lang";

export interface Scheduler {
  request(cb: (dtMs: number) => void): unknown;
  cancel(handle: unknown): void;
}

export type RunState = "idle" | "running" | "paused" | "done" | "error";

export interface TurtleState {
  pos: Vec;
  heading: Vec;
  right: Vec;
  up: Vec;
  penDown: boolean;
  color: string;
  width: number;
}

export interface Snapshot {
  state: RunState;
  segments: Segment[];
  turtle: TurtleState;
  /** position of the command executed last, while a run is in progress */
  current: { line: number; col: number } | null;
  error: LogoErrorInfo | null;
  /** true when the program was edited while it was running */
  stale: boolean;
}

const HOME: TurtleState = {
  pos: [0, 0, 0], heading: [0, 1, 0], right: [1, 0, 0], up: [0, 0, 1], penDown: true, color: "#16866a", width: 3,
};

export class Controller {
  private state: RunState = "idle";
  private machine: Machine | null = null;
  private gen: Generator<Step, void, void> | null = null;
  private current: Step | null = null;
  private error: LogoErrorInfo | null = null;
  private listeners = new Set<() => void>();

  constructor(private opts: { source: () => { source: string; mode: Mode }; scheduler: Scheduler }) {}

  subscribe(fn: () => void) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
  private emit() { for (const fn of this.listeners) fn(); }

  snapshot(): Snapshot {
    const m = this.machine;
    return {
      state: this.state,
      segments: m ? m.segments : [],
      turtle: m ? { pos: m.pos, heading: m.heading, right: m.right, up: m.up, penDown: m.penDown, color: m.color, width: m.width } : HOME,
      current: this.current,
      error: this.error,
      stale: false,
    };
  }

  reset() {
    this.machine = null;
    this.gen = null;
    this.current = null;
    this.error = null;
    this.state = "idle";
    this.emit();
  }

  /** prepares a fresh run; returns false when the program does not parse */
  private start(): boolean {
    this.reset();
    const { source, mode } = this.opts.source();
    try {
      this.machine = new Machine(parse(source, mode));
      this.gen = this.machine.steps();
      return true;
    } catch (e) {
      if (!(e instanceof LogoError)) throw e;
      this.error = e.info();
      this.state = "error";
      this.emit();
      return false;
    }
  }

  /** executes exactly one operation; returns false when the program ended */
  private advance(): boolean {
    try {
      const r = this.gen!.next();
      if (r.done) { this.current = null; this.state = "done"; return false; }
      this.current = r.value;
      return true;
    } catch (e) {
      if (!(e instanceof LogoError)) throw e;
      this.error = e.info();
      this.current = null;
      this.state = "error";
      return false;
    }
  }

  step() {
    if (this.state === "idle" || this.state === "done" || this.state === "error") {
      if (!this.start()) return;
    }
    this.state = "paused";
    this.advance();
    this.emit();
  }
}
EOF
