describe("controller: run, pause, resume", () => {
  test("run animates at the chosen speed: ops per second, only drawing commands cost time", () => {
    const { c, sched } = make("niech a 1\npowtorz 10 [np 1]");
    c.setSpeed(10); // visible commands per second
    c.run();
    expect(c.snapshot().state).toBe("running");
