    expect(c.snapshot().segments).toHaveLength(5);
    expect(c.snapshot().state).toBe("running");
  });
  test("instant speed finishes the program in one frame with the same strokes as run()", () => {
    const src = "powtorz 12 [powtorz 4 [np 100 pw 90] pw 30]";
    const { c, sched } = make(src);
    c.setSpeed(Infinity);
    c.run();
    sched.tick(16);
    const s = c.snapshot();
    expect(s.state).toBe("done");
    expect(s.segments).toEqual(run(src, "2d").segments);
    expect(sched.pending).toBe(false);
  });
  test("pause freezes the drawing; resume continues from the same place", () => {
    const { c, sched } = make("powtorz 10 [np 1]");
    c.setSpeed(10);
    c.run();
    sched.tick(300);
    c.pause();
    expect(c.snapshot().state).toBe("paused");
    sched.tick(1000);
    expect(c.snapshot().segments).toHaveLength(3);
    c.resume();
    expect(c.snapshot().state).toBe("running");
    sched.tick(200);
    expect(c.snapshot().segments).toHaveLength(5);
  });
  test("stepping while paused, then resuming, keeps one continuous run", () => {
    const { c, sched } = make("powtorz 5 [np 1]");
    c.setSpeed(10);
    c.run(); sched.tick(100); c.pause();
    c.step(); c.step();
    expect(c.snapshot().segments).toHaveLength(3);
    c.resume(); sched.tick(10000);
    expect(c.snapshot().segments).toHaveLength(5);
    expect(c.snapshot().state).toBe("done");
  });
  test("run restarts from scratch, also while running", () => {
    const { c, sched } = make("powtorz 4 [np 1]");
    c.setSpeed(10);
    c.run(); sched.tick(300);
    c.run();
    expect(c.snapshot().segments).toHaveLength(0);
    sched.tick(100);
    expect(c.snapshot().segments).toHaveLength(1);
