import { test, expect, describe } from "bun:test";
import { Workspace, type KV } from "../src/core/workspace";
import { exampleById } from "../src/core/examples";

class MemoryKV implements KV {
  data = new Map<string, string>();
  getItem(k: string) { return this.data.get(k) ?? null; }
  setItem(k: string, v: string) { this.data.set(k, v); }
  removeItem(k: string) { this.data.delete(k); }
}

describe("workspace: drafts and persistence", () => {
  test("a fresh workspace starts in 2D with a starter program per mode", () => {
    const w = new Workspace(new MemoryKV());
    expect(w.mode).toBe("2d");
    expect(w.draft("2d")).toBe(exampleById("kwadrat")!.code);
    expect(w.draft("3d")).toBe(exampleById("schody")!.code);
  });
  test("each mode keeps its own draft and both survive a reload", () => {
    const kv = new MemoryKV();
    const a = new Workspace(kv);
    a.setDraft("2d", "np 42");
    a.setDraft("3d", "gora 10 np 7");
    a.setMode("3d");
    const b = new Workspace(kv);
    expect(b.mode).toBe("3d");
    expect(b.draft("2d")).toBe("np 42");
    expect(b.draft("3d")).toBe("gora 10 np 7");
  });
  test("an empty draft is a real draft, not a reason to reload the starter", () => {
    const kv = new MemoryKV();
    new Workspace(kv).setDraft("2d", "");
    expect(new Workspace(kv).draft("2d")).toBe("");
  });
  test("unusable storage never breaks the workspace", () => {
    const broken: KV = {
      getItem() { throw new Error("denied"); },
      setItem() { throw new Error("quota"); },
      removeItem() { throw new Error("denied"); },
    };
    const w = new Workspace(broken);
    w.setDraft("2d", "np 1");
    expect(w.draft("2d")).toBe("np 1");
  });
});

describe("workspace: loading programs never silently destroys a draft", () => {
  test("loading an example switches to its mode and replaces that mode's draft", () => {
    const w = new Workspace(new MemoryKV());
    w.loadExample("kula");
    expect(w.mode).toBe("3d");
    expect(w.draft("3d")).toBe(exampleById("kula")!.code);
    expect(w.draft("2d")).toBe(exampleById("kwadrat")!.code);
  });
  test("a modified draft is kept as a backup and can be restored with undo", () => {
    const w = new Workspace(new MemoryKV());
    w.setDraft("2d", "np 1 pw 90 np 2");
    const r = w.loadExample("gwiazda");
    expect(r.backedUp).toBe(true);
    expect(w.draft("2d")).toBe(exampleById("gwiazda")!.code);
    expect(w.backups()).toHaveLength(1);
    expect(w.backups()[0]).toMatchObject({ mode: "2d", source: "np 1 pw 90 np 2" });
    r.undo();
    expect(w.draft("2d")).toBe("np 1 pw 90 np 2");
    expect(w.mode).toBe("2d");
  });
  test("an untouched example or empty draft needs no backup", () => {
    const w = new Workspace(new MemoryKV());
    expect(w.loadExample("gwiazda").backedUp).toBe(false);
    w.setDraft("2d", "   \n");
    expect(w.loadExample("rozeta").backedUp).toBe(false);
    expect(w.backups()).toHaveLength(0);
  });
  test("undo returns to the mode that was active before", () => {
    const w = new Workspace(new MemoryKV());
    w.setDraft("3d", "gora 1 np 1");
    const r = w.loadExample("helisa");
    r.undo();
    expect(w.draft("3d")).toBe("gora 1 np 1");
  });
  test("backups survive a reload, are deduplicated and capped", () => {
    const kv = new MemoryKV();
    const w = new Workspace(kv);
    for (let i = 0; i < 15; i++) { w.setDraft("2d", `np ${i + 1}`); w.loadExample("kwadrat"); }
    expect(w.backups().length).toBe(10);
    expect(w.backups()[0].source).toBe("np 15");
    expect(new Workspace(kv).backups()).toHaveLength(10);
    w.setDraft("2d", "np 15"); w.loadExample("kwadrat");
    expect(w.backups().filter((b) => b.source === "np 15")).toHaveLength(1);
  });
  test("restoring a backup is itself protected", () => {
    const w = new Workspace(new MemoryKV());
    w.setDraft("2d", "np 1 np 2");
    w.loadExample("gwiazda");
    w.setDraft("2d", "np 99");
    const id = w.backups()[0].id;
    const r = w.restoreBackup(id);
    expect(w.draft("2d")).toBe("np 1 np 2");
    expect(r.backedUp).toBe(true);
    expect(w.backups().some((b) => b.source === "np 99")).toBe(true);
  });
  test("loading shared or opened text follows the same protection", () => {
    const w = new Workspace(new MemoryKV());
    w.setDraft("3d", "gora 1 np 5");
    const r = w.loadText("np 100", "3d");
    expect(r.backedUp).toBe(true);
    expect(w.draft("3d")).toBe("np 100");
    expect(w.mode).toBe("3d");
  });
});
EOF
