import type { Mode } from "../lang/types";
import { EXAMPLES, exampleById } from "./examples";

export interface KV {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export interface Backup {
  id: string;
  mode: Mode;
  source: string;
  at: number;
}

export interface LoadResult {
  /** true when the replaced draft was kept in the backups */
  backedUp: boolean;
  undo(): void;
}

const P = "logomocja:v1:";
const MAX_BACKUPS = 10;

/** Drafts per mode, the active mode and draft backups; persisted in a key-value store. */
export class Workspace {
  mode: Mode = "2d";
  private drafts: Record<Mode, string>;
  private saved: Backup[] = [];
  private counter = 0;

  constructor(private kv: KV) {
    const d2 = this.read("draft:2d");
    const d3 = this.read("draft:3d");
    this.drafts = { "2d": d2 ?? exampleById("kwadrat")!.code, "3d": d3 ?? exampleById("schody")!.code };
