    expect(decodeShare(encodeShare(long, "2d"))!.source).toBe(long);
  });
  test("an empty program is a valid permalink", () => {
    expect(decodeShare(encodeShare("", "2d"))).toEqual({ source: "", mode: "2d" });
  });
  test("other routes, missing or damaged parameters are not permalinks", () => {
    expect(decodeShare("#/wyzwania")).toBeNull();
    expect(decodeShare("")).toBeNull();
    expect(decodeShare("#/pracownia")).toBeNull();
    expect(decodeShare("#/pracownia?tryb=4d&kod=bnAgMQ")).toBeNull();
    expect(decodeShare("#/pracownia?tryb=2d&kod=%%%")).toBeNull();
    expect(decodeShare("#/pracownia?tryb=2d&kod=_w")).toBeNull(); // invalid UTF-8 byte
  });
  test("the mode defaults to 2d when the parameter is absent", () => {
    expect(decodeShare("#/pracownia?kod=bnAgMQ")).toEqual({ source: "np 1", mode: "2d" });
  });
});

