    expect(f.filename).toBe("logomocja-3d.logo");
    expect(f.content).toBe("np 1\nkąt");
    expect(f.type).toContain("text/plain");
  });
  test("opening normalises line endings and a byte-order mark", () => {
    expect(fromLogoFile("﻿np 1\r\nnp 2\r\n")).toBe("np 1\nnp 2\n");
  });
  test("a file using pitch or roll commands opens in 3D, other files keep the current mode", () => {
    expect(guessMode("np 1\nGORA 20", "2d")).toBe("3d");
    expect(guessMode("; gora w komentarzu\nnp 1", "2d")).toBe("2d");
    expect(guessMode("np 1", "3d")).toBe("3d");
  });
});
