import type { Mode } from "../lang/types";

export const SHARE_ROUTE = "#/pracownia";

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = "";
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromBase64Url(s: string): string | null {
  if (!/^[A-Za-z0-9_-]*$/.test(s)) return null;
  try {
    const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

/** the location hash that reopens this program in this mode */
export function encodeShare(source: string, mode: Mode): string {
  return `${SHARE_ROUTE}?tryb=${mode}&kod=${toBase64Url(source)}`;
}

export function decodeShare(hash: string): { source: string; mode: Mode } | null {
  const m = /^#\/pracownia\?(.*)$/.exec(hash);
  if (!m) return null;
  const params = new URLSearchParams(m[1]);
  const code = params.get("kod");
  if (code === null) return null;
  const mode = params.get("tryb") ?? "2d";
  if (mode !== "2d" && mode !== "3d") return null;
  const source = fromBase64Url(code);
  return source === null ? null : { source, mode };
}
EOF
