import { lex } from "../lang/lexer";
import { COMMANDS, SPATIAL } from "../lang/keywords";
import type { Mode } from "../lang/types";

export function toLogoFile(source: string, mode: Mode) {
  return { filename: `logomocja-${mode}.logo`, content: source, type: "text/plain;charset=utf-8" };
}

export function fromLogoFile(text: string): string {
  return text.replace(/^﻿/, "").replace(/\r\n?/g, "\n");
}

/** pitch and roll commands only make sense in 3D; otherwise the current mode stays */
export function guessMode(source: string, current: Mode): Mode {
  const spatial = lex(source).some((t) => t.k === "word" && SPATIAL.has(COMMANDS.get(t.text)!));
  return spatial ? "3d" : current;
}
