import { test, expect, describe } from "bun:test";
import { CHALLENGES, checkChallenge, ChallengeProgress } from "../src/core/challenges";
import type { KV } from "../src/core/workspace";

class MemoryKV implements KV {
  data = new Map<string, string>();
  getItem(k: string) { return this.data.get(k) ?? null; }
  setItem(k: string, v: string) { this.data.set(k, v); }
  removeItem(k: string) { this.data.delete(k); }
}

const get = (id: string) => CHALLENGES.find((c) => c.id === id)!;

describe("challenges: catalogue", () => {
  test("at least five tasks, each with text, a mode and a reference drawing that passes its own check", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
    for (const c of CHALLENGES) {
      expect(c.title.length, c.id).toBeGreaterThan(2);
      expect(c.task.length, c.id).toBeGreaterThan(20);
      expect(checkChallenge(c, c.solution), c.id).toMatchObject({ pass: true });
    }
  });
});

describe("challenges: checker", () => {
  const square = get("kwadrat");
  test("a different program drawing the same square passes", () => {
    expect(checkChallenge(square, "np 100 pw 90 np 100 pw 90 np 50 np 50 pw 90 np 100 pw 90").pass).toBe(true);
  });
  test("direction of travel and pen-up travel do not matter, only the ink", () => {
    expect(checkChallenge(square, "pod np 100 opu pw 180 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100").pass).toBe(false);
    expect(checkChallenge(square, "pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 pod np 50 opu").pass).toBe(true);
  });
  test("a drawing within a few units still passes", () => {
    expect(checkChallenge(square, "powtorz 4 [np 101 pw 90]").pass).toBe(true);
  });
  test("a square that is too small fails and says what is missing", () => {
    const r = checkChallenge(square, "powtorz 4 [np 80 pw 90]");
    expect(r.pass).toBe(false);
    expect(r.reason).toMatch(/brak/i);
  });
  test("extra lines fail and say there is too much", () => {
    const r = checkChallenge(square, "powtorz 4 [np 100 pw 90] pw 45 np 150");
    expect(r.pass).toBe(false);
    expect(r.reason).toMatch(/za dużo|nadmiar|ponad/i);
  });
  test("an empty drawing and a program with an error both fail with a reason", () => {
    expect(checkChallenge(square, "pod np 100")).toMatchObject({ pass: false, reason: expect.stringMatching(/nic/i) });
    const r = checkChallenge(square, "np 100\nnp 1 / 0");
    expect(r.pass).toBe(false);
    expect(r.reason).toContain("wiersz 2");
  });
  test("a task that needs a colour checks it", () => {
    const c = get("kolorowy");
    expect(checkChallenge(c, 'kolor "#c1763d" powtorz 4 [np 80 pw 90]').pass).toBe(true);
    const r = checkChallenge(c, "powtorz 4 [np 80 pw 90]");
    expect(r.pass).toBe(false);
    expect(r.reason).toMatch(/kolor/i);
  });
  test("a 3D task compares in space, not only the shadow on the floor", () => {
    const c = get("pionowy");
    expect(c.mode).toBe("3d");
    expect(checkChallenge(c, "powtorz 4 [np 100 pw 90]").pass).toBe(false);
    expect(checkChallenge(c, "gora 90 powtorz 4 [np 100 pw 90]").pass).toBe(true);
    expect(checkChallenge(c, "gora 90 powtorz 4 [np 100 lw 90]").pass).toBe(false);
  });
  test("the circle task accepts 72 short steps as well as 36", () => {
    expect(checkChallenge(get("okrag"), "powtorz 72 [np 5 pw 5]").pass).toBe(true);
    expect(checkChallenge(get("okrag"), "powtorz 36 [np 10 lw 10]").pass).toBe(false);
  });
});

describe("challenges: progress", () => {
  test("a pass is remembered across reloads together with the solution", () => {
    const kv = new MemoryKV();
    const p = new ChallengeProgress(kv);
    expect(p.isSolved("kwadrat")).toBe(false);
    p.record("kwadrat", { pass: true, reason: "ok" }, "powtorz 4 [np 100 pw 90]");
    const q = new ChallengeProgress(kv);
    expect(q.isSolved("kwadrat")).toBe(true);
    expect(q.source("kwadrat")).toBe("powtorz 4 [np 100 pw 90]");
    expect(q.solvedCount()).toBe(1);
  });
  test("a later failed attempt keeps the challenge solved but saves the new text as the working draft", () => {
    const kv = new MemoryKV();
    const p = new ChallengeProgress(kv);
    p.record("kwadrat", { pass: true, reason: "ok" }, "good");
    p.record("kwadrat", { pass: false, reason: "źle" }, "work in progress");
    const q = new ChallengeProgress(kv);
    expect(q.isSolved("kwadrat")).toBe(true);
    expect(q.source("kwadrat")).toBe("work in progress");
    expect(q.lastReason("kwadrat")).toBe("źle");
  });
  test("saving a draft without checking, and damaged storage, are harmless", () => {
    const kv = new MemoryKV();
    const p = new ChallengeProgress(kv);
    p.saveDraft("okrag", "np 1");
    expect(new ChallengeProgress(kv).source("okrag")).toBe("np 1");
    kv.setItem("logomocja:v1:challenges", "{not json");
    expect(new ChallengeProgress(kv).solvedCount()).toBe(0);
  });
});
