import { run } from "../lang";
import type { Mode, Segment, Vec } from "../lang/types";
import type { KV } from "./workspace";

export interface Challenge {
  id: string;
  title: string;
  mode: Mode;
  /** what to draw, in Polish */
  task: string;
  hint: string;
  /** a reference program; its drawing is the expected result */
  solution: string;
