    hint: "Kąt między ramionami to 144°, nie 72°.",
    solution: "powtorz 5 [np 150 pw 144]",
    starter: "; Gwiazda z pięciu odcinków po 150.\n",
  },
  {
    id: "schodki",
    title: "Schodki",
    mode: "2d",
    task: "Narysuj pięć schodków: 30 do przodu, skręt w prawo o 90, 30 do przodu i skręt w lewo o 90. Powtórz to pięć razy bez podnoszenia pisaka.",
    hint: "Jeden stopień to cztery polecenia; resztę zrobi powtorz.",
    solution: "powtorz 5 [np 30 pw 90 np 30 lw 90]",
    starter: "; Pięć schodków.\n",
  },
  {
    id: "okrag",
    title: "Okrąg",
    mode: "2d",
    task: "Narysuj okrąg z 36 krótkich odcinków po 10, skręcając w prawo. Okrąg ma leżeć po prawej stronie od startu.",
    hint: "36 skrętów po 10° daje pełny obrót 360°.",
