    return { pass: false, reason: `Program zawiera błąd (wiersz ${r.error.line}, kolumna ${r.error.column}): ${r.error.message}` };
  }
  if (r.segments.length === 0) return { pass: false, reason: "Nic nie narysowano: opuść pisak i ruszaj żółwiem." };
  const mine = sample(r.segments);
  const want = sample(target);
  const covered = coverage(want, new Grid(mine));
  const clean = coverage(mine, new Grid(want));
  const problems: string[] = [];
  if (covered < REQUIRED) problems.push(`Brakuje części rysunku: pokryto ${Math.round(covered * 100)}% wzoru.`);
  if (clean < REQUIRED) problems.push(`Na rysunku jest za dużo: ${Math.round((1 - clean) * 100)}% linii leży poza wzorem.`);
  if (problems.length) return { pass: false, reason: problems.join(" ") };
  if (c.colors) {
    const bad = r.segments.find((s) => !c.colors!.includes(s.color));
    if (bad) return { pass: false, reason: `Rysunek jest dobry, ale zły jest kolor ${bad.color}. Użyj koloru ${c.colors.join(" lub ")}.` };
  }
  return { pass: true, reason: "Zgadza się z wzorem." };
}

interface Entry { solved: boolean; source: string; reason?: string; at?: number }

const KEY = "logomocja:v1:challenges";

/** Which challenges are solved, the last reason, and the user's text per challenge. */
export class ChallengeProgress {
  private data: Record<string, Entry> = {};
  constructor(private kv: KV) {
    try {
      const raw = kv.getItem(KEY);
      const parsed = raw ? JSON.parse(raw) : {};
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) this.data = parsed;
    } catch { /* damaged storage: start empty */ }
  }
  private save() {
    try { this.kv.setItem(KEY, JSON.stringify(this.data)); } catch { /* stay in memory */ }
  }
  isSolved(id: string) { return this.data[id]?.solved === true; }
  solvedCount() { return Object.values(this.data).filter((e) => e && e.solved === true).length; }
  source(id: string): string | null { return typeof this.data[id]?.source === "string" ? this.data[id].source : null; }
  lastReason(id: string): string | null { return this.data[id]?.reason ?? null; }
  saveDraft(id: string, source: string) {
    this.data[id] = { ...this.data[id], solved: this.data[id]?.solved === true, source };
    this.save();
  }
  record(id: string, result: CheckResult, source: string) {
    this.data[id] = {
      solved: this.isSolved(id) || result.pass,
      source,
      reason: result.reason,
      at: Date.now(),
    };
    this.save();
  }
}
