import { COMMANDS, DEFINE, END, REPCOUNT } from "../lang/keywords";
import { norm } from "../lang/keywords";

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const TOKEN = /(;.*$)|("[^"\n]*"?)|(\d+(?:\.\d+)?|\.\d+)|(ma:)|(:?[\p{L}_][\p{L}\p{N}_]*)|([[\]()])|([+\-*/<>=,])/giu;

/** names introduced by `oto name` lines, so calls to them can be coloured as procedures */
export function procedureNames(source: string): Set<string> {
  const out = new Set<string>();
  for (const m of source.matchAll(/^[ \t]*(?:oto|to)[ \t]+:?([\p{L}_][\p{L}\p{N}_]*)/gimu)) out.add(norm(m[1]));
  return out;
}

/** HTML for one source line; every character of the line is kept so the overlay lines up with the textarea */
export function highlightLine(line: string, procs: Set<string>, errorCol?: number): string {
  let out = "";
  let last = 0;
  const wrapError = (html: string, start: number, end: number) =>
    errorCol !== undefined && errorCol >= start && errorCol < end ? html : null;
  void wrapError;
  const pieces: { start: number; end: number; cls: string }[] = [];
  for (const m of line.matchAll(TOKEN)) {
    const start = m.index!;
    const text = m[0];
    let cls = "";
    if (m[1]) cls = "tk-com";
    else if (m[2]) cls = "tk-str";
    else if (m[3]) cls = "tk-num";
    else if (m[4]) cls = "tk-def";
    else if (m[5]) {
      const w = norm(text.replace(/^:/, ""));
      if (COMMANDS.has(w)) cls = "tk-cmd";
      else if (DEFINE.has(w) || END.has(w)) cls = "tk-def";
      else if (REPCOUNT.has(w)) cls = "tk-val";
      else if (procs.has(w) && !text.startsWith(":")) cls = "tk-proc";
      else cls = "tk-name";
    } else if (m[6]) cls = "tk-br";
    else cls = "tk-op";
    pieces.push({ start, end: start + text.length, cls });
  }
  // the error squiggle covers the token that starts at errorCol (0-based, in UTF-16 units)
  let errEnd = -1;
  if (errorCol !== undefined) {
    const hit = pieces.find((p) => p.start === errorCol);
    errEnd = hit ? hit.end : Math.min(line.length, errorCol + 1);
  }
  const emit = (from: number, to: number, cls: string) => {
    if (to <= from) return;
    let text = esc(line.slice(from, to));
    if (errorCol !== undefined && from >= errorCol && to <= errEnd) text = `<span class="tk-err">${text}</span>`;
    out += cls ? `<span class="${cls}">${text}</span>` : text;
  };
  // split pieces at the error boundaries so the squiggle wraps exactly the token
  const cuts = new Set<number>();
  if (errorCol !== undefined) { cuts.add(errorCol); cuts.add(errEnd); }
  const segs: { start: number; end: number; cls: string }[] = [];
  let pos = 0;
  for (const p of pieces) {
    if (p.start > pos) segs.push({ start: pos, end: p.start, cls: "" });
    segs.push(p);
    pos = p.end;
  }
  if (pos < line.length) segs.push({ start: pos, end: line.length, cls: "" });
  for (const s of segs) {
    let a = s.start;
    for (const c of [...cuts].sort((x, y) => x - y)) {
      if (c > a && c < s.end) { emit(a, c, s.cls); a = c; }
    }
    emit(a, s.end, s.cls);
  }
  void last;
  return out;
}
