import type { LogoErrorInfo } from "../lang/types";
import { h } from "./dom";
import { highlightLine, procedureNames } from "./highlight";

export interface EditorOptions {
  label: string;
  onInput: (text: string) => void;
}

/** A textarea with a syntax-highlighted overlay, a line-number gutter, an error marker and an execution-line highlight. */
export class Editor {
  readonly el: HTMLElement;
  readonly textarea: HTMLTextAreaElement;
  private under: HTMLElement;
  private underInner: HTMLElement;
  private gutterInner: HTMLElement;
  private error: LogoErrorInfo | null = null;
  private active: number | null = null;
  private lines: string[] = [];

  constructor(private opts: EditorOptions) {
    this.textarea = h("textarea", {
      class: "ed-ta",
      spellcheck: "false",
      autocapitalize: "off",
      autocomplete: "off",
      autocorrect: "off",
      wrap: "off",
      "aria-label": opts.label,
      "aria-describedby": "ed-help",
    });
    this.underInner = h("div", { class: "ed-under-inner" });
    this.under = h("div", { class: "ed-under", "aria-hidden": "true" }, this.underInner);
    this.gutterInner = h("div", { class: "ed-gutter-inner" });
    const gutter = h("div", { class: "ed-gutter", "aria-hidden": "true" }, this.gutterInner);
    this.el = h("div", { class: "ed" }, gutter, h("div", { class: "ed-body" }, this.under, this.textarea));
    this.textarea.addEventListener("input", () => {
      this.render();
      this.opts.onInput(this.textarea.value);
    });
    this.textarea.addEventListener("scroll", () => this.syncScroll());
    this.render();
  }

  get value() { return this.textarea.value; }

  setValue(text: string) {
    this.textarea.value = text;
    this.render();
  }

  setError(e: LogoErrorInfo | null) {
    this.error = e;
    this.render();
    if (e) this.reveal(e.line);
  }

  setActive(line: number | null) {
    if (line === this.active) return;
    this.active = line;
    this.render();
    if (line) this.reveal(line);
  }

  focus() { this.textarea.focus(); }

  /** moves the caret to a line and column (1-based) */
  goTo(line: number, column: number) {
    const lines = this.textarea.value.split("\n");
    let idx = 0;
    for (let i = 0; i < line - 1 && i < lines.length; i++) idx += lines[i].length + 1;
    const lineText = lines[line - 1] ?? "";
    idx += Math.min(lineText.length, Array.from(lineText).slice(0, column - 1).join("").length);
    this.textarea.focus();
    this.textarea.setSelectionRange(idx, idx);
    this.reveal(line);
  }

  private reveal(line: number) {
    const lh = this.lineHeight();
    const top = (line - 1) * lh;
    const ta = this.textarea;
    if (!ta.clientHeight) return;
    if (top < ta.scrollTop) ta.scrollTop = top;
    else if (top + lh * 2 > ta.scrollTop + ta.clientHeight) ta.scrollTop = top + lh * 2 - ta.clientHeight;
    this.syncScroll();
  }

  private lineHeight() {
    const v = parseFloat(getComputedStyle(this.textarea).lineHeight);
    return Number.isFinite(v) ? v : 22;
  }

  private syncScroll() {
    const { scrollTop, scrollLeft } = this.textarea;
    this.underInner.style.transform = `translate(${-scrollLeft}px, ${-scrollTop}px)`;
    this.gutterInner.style.transform = `translateY(${-scrollTop}px)`;
  }

  private render() {
    const text = this.textarea.value;
    this.lines = text.split("\n");
    const procs = procedureNames(text);
    const err = this.error;
    const rows: HTMLElement[] = [];
    const nums: HTMLElement[] = [];
    this.lines.forEach((line, i) => {
      const n = i + 1;
      const isErr = err?.line === n;
      const cls = "ln" + (this.active === n ? " is-active" : "") + (isErr ? " is-error" : "");
      let errIdx: number | undefined;
      if (isErr) errIdx = Array.from(line).slice(0, err!.column - 1).join("").length;
      const row = h("div", { class: cls });
      row.innerHTML = highlightLine(line, procs, errIdx) || "&#8203;";
      rows.push(row);
      nums.push(h("div", { class: "gn" + (this.active === n ? " is-active" : "") + (isErr ? " is-error" : "") }, String(n)));
    });
    this.underInner.replaceChildren(...rows);
    this.gutterInner.replaceChildren(...nums);
    // keep the scrollable area as wide as the longest line so the overlay and textarea scroll together
    this.syncScroll();
  }
}
