/** colours the canvases need, read from the CSS custom properties of the current theme */
export interface SheetColors {
  sheet: string;
  grid: string;
  axis: string;
  ink: string;
  muted: string;
  accent: string;
  axisX: string;
  axisY: string;
  axisZ: string;
}

export function hexToRgb(hex: string): [number, number, number] {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return [0.5, 0.5, 0.5];
  const n = parseInt(m[1], 16);
  return [(n >> 16) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

export function readSheetColors(el: Element): SheetColors {
  const cs = getComputedStyle(el);
  const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    sheet: v("--sheet", "#fbf9f2"),
    grid: v("--sheet-grid", "#d9d6cb"),
