export interface GestureHandlers {
  /** one pointer dragged; `pan` is true for shift/right/middle drags */
  drag(dx: number, dy: number, pan: boolean): void;
  /** two pointers: scale change about a centre, plus how far the centre moved */
  pinch(scale: number, cx: number, cy: number, dx: number, dy: number): void;
  wheel(deltaY: number, x: number, y: number): void;
  key(e: KeyboardEvent): boolean;
}

/** pointer, wheel and keyboard input for a canvas, with positions relative to the element */
export function attachGestures(el: HTMLElement, hd: GestureHandlers) {
  const pts = new Map<number, { x: number; y: number }>();
  let lastDist = 0;
  let lastCx = 0;
  let lastCy = 0;
  let pan = false;
  const rel = (e: PointerEvent) => {
    const r = el.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const two = () => {
    const [a, b] = [...pts.values()];
    return { d: Math.hypot(a.x - b.x, a.y - b.y) || 1, cx: (a.x + b.x) / 2, cy: (a.y + b.y) / 2 };
  };

  el.addEventListener("pointerdown", (e) => {
    el.setPointerCapture?.(e.pointerId);
    pts.set(e.pointerId, rel(e));
    pan = e.shiftKey || e.button === 1 || e.button === 2 || e.ctrlKey;
    if (pts.size === 2) { const t = two(); lastDist = t.d; lastCx = t.cx; lastCy = t.cy; }
    el.classList.add("is-dragging");
  });
  el.addEventListener("pointermove", (e) => {
    if (!pts.has(e.pointerId)) return;
    const prev = pts.get(e.pointerId)!;
    const cur = rel(e);
    pts.set(e.pointerId, cur);
    if (pts.size === 1) hd.drag(cur.x - prev.x, cur.y - prev.y, pan);
    else if (pts.size === 2) {
      const t = two();
      hd.pinch(t.d / lastDist, t.cx, t.cy, t.cx - lastCx, t.cy - lastCy);
      lastDist = t.d; lastCx = t.cx; lastCy = t.cy;
    }
  });
  const up = (e: PointerEvent) => {
    pts.delete(e.pointerId);
    if (pts.size === 0) el.classList.remove("is-dragging");
    if (pts.size === 1) { /* continue as a single-finger drag from here */ }
  };
  el.addEventListener("pointerup", up);
  el.addEventListener("pointercancel", up);
  el.addEventListener("contextmenu", (e) => e.preventDefault());
  el.addEventListener("wheel", (e) => {
    e.preventDefault();
    const r = el.getBoundingClientRect();
    const unit = e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? 100 : 1;
    hd.wheel(e.deltaY * unit, e.clientX - r.left, e.clientY - r.top);
  }, { passive: false });
  el.addEventListener("keydown", (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (hd.key(e)) e.preventDefault();
  });
}
