      for (const s of this.data.ghost) { ctx.moveTo(X(s.from[0]), Y(s.from[1])); ctx.lineTo(X(s.to[0]), Y(s.to[1])); }
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
    const segs = this.data.segments;
    // consecutive strokes with the same pen are drawn as one path
    let i = 0;
    while (i < segs.length) {
      const s0 = segs[i];
      ctx.strokeStyle = s0.color;
      ctx.lineWidth = s0.width;
      ctx.beginPath();
      let j = i;
      while (j < segs.length && segs[j].color === s0.color && segs[j].width === s0.width) {
        ctx.moveTo(X(segs[j].from[0]), Y(segs[j].from[1]));
        ctx.lineTo(X(segs[j].to[0]), Y(segs[j].to[1]));
        j++;
      }
      ctx.stroke();
      i = j;
    }
    if (chrome) {
      // origin marker
      ctx.strokeStyle = c.ink;
      ctx.fillStyle = c.sheet;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(X(0), Y(0), 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = c.muted;
      ctx.font = "12px ui-monospace, SFMono-Regular, Menlo, monospace";
      ctx.textBaseline = "top";
      ctx.fillText("0", X(0) + 7, Y(0) + 6);
      const t = this.data.turtle;
      if (t) this.paintTurtle(ctx, t, X, Y);
      this.scaleLabel.textContent = `siatka co ${step}`;
    }
  }

  private paintTurtle(ctx: CanvasRenderingContext2D, t: TurtleState, X: (x: number) => number, Y: (y: number) => number) {
    const px = X(t.pos[0]), py = Y(t.pos[1]);
    // heading projected onto the page; in 3D fallback a vertical heading still shows its screen part
    const hx = t.heading[0], hy = -t.heading[1];
    const len = Math.hypot(hx, hy);
    const ang = len < 1e-6 ? -Math.PI / 2 : Math.atan2(hy, hx);
    const size = 11;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(ang);
    ctx.beginPath();
    ctx.moveTo(size * 1.1, 0);
    ctx.lineTo(-size * 0.7, size * 0.65);
    ctx.lineTo(-size * 0.35, 0);
    ctx.lineTo(-size * 0.7, -size * 0.65);
    ctx.closePath();
    ctx.fillStyle = t.penDown ? this.colors.accent : this.colors.sheet;
    ctx.globalAlpha = 0.92;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.lineWidth = 1.75;
    ctx.strokeStyle = this.colors.ink;
    ctx.stroke();
    ctx.restore();
  }

  /** PNG of the whole drawing on the sheet colour, without grid or turtle */
  async exportPng(): Promise<Blob> {
    const segs = this.data.segments;
    let minX = 0, maxX = 0, minY = 0, maxY = 0;
    if (segs.length) {
      minX = Infinity; minY = Infinity; maxX = -Infinity; maxY = -Infinity;
      for (const s of segs) for (const p of [s.from, s.to]) {
        minX = Math.min(minX, p[0]); maxX = Math.max(maxX, p[0]); minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]);
      }
    }
    const spanX = Math.max(maxX - minX, 20), spanY = Math.max(maxY - minY, 20);
    const pad = 48;
    const k = Math.min(1600 / spanX, 1600 / spanY, 6);
    const W = Math.round(spanX * k + pad * 2), H = Math.round(spanY * k + pad * 2);
    const cv = document.createElement("canvas");
    cv.width = W; cv.height = H;
    const ctx = cv.getContext("2d")!;
    const saved = { s: this.scale, x: this.ox, y: this.oy, t: this.data.turtle, g: this.data.ghost };
    this.scale = k;
    this.ox = pad - minX * k;
    this.oy = pad + maxY * k;
    this.data = { ...this.data, turtle: null, ghost: undefined };
    this.paint(ctx, W, H, 1, false);
    this.scale = saved.s; this.ox = saved.x; this.oy = saved.y;
    this.data = { ...this.data, turtle: saved.t, ghost: saved.g };
    return new Promise((res, rej) => cv.toBlob((b) => (b ? res(b) : rej(new Error("PNG nie powstał"))), "image/png"));
  }
}
