import type { Segment, Vec } from "../lang/types";
import type { TurtleState } from "../core/controller";
import { attachGestures } from "./gestures";
import { h } from "./dom";
import { hexToRgb, readSheetColors, type SheetColors } from "./theme";
import type { SceneData } from "./view2d";

type Mat = Float32Array;

const VERT = `
attribute vec3 aA;
attribute vec3 aB;
attribute vec2 aCorner;
attribute vec4 aColor;
attribute float aWidth;
uniform mat4 uView;
uniform mat4 uProj;
uniform vec2 uViewport;
uniform float uNear;
varying vec4 vColor;
void main() {
  vColor = aColor;
  vec4 a = uView * vec4(aA, 1.0);
  vec4 b = uView * vec4(aB, 1.0);
