      out[o++] = l.b[0]; out[o++] = l.b[1]; out[o++] = l.b[2];
      out[o++] = cx; out[o++] = cy;
      out[o++] = l.rgba[0]; out[o++] = l.rgba[1]; out[o++] = l.rgba[2]; out[o++] = l.rgba[3];
