const FOV = (45 * Math.PI) / 180;
const DEFAULT_YAW = (-32 * Math.PI) / 180;
const DEFAULT_PITCH = (26 * Math.PI) / 180;

interface Batch { buf: WebGLBuffer; count: number }

export class View3D {
  readonly el: HTMLElement;
  readonly canvas: HTMLCanvasElement;
  private gl: WebGLRenderingContext;
  private prog: WebGLProgram;
  private loc: Record<string, number> = {};
  private uni: Record<string, WebGLUniformLocation | null> = {};
  private w = 300;
  private hgt = 300;
  private dpr = 1;
  private target: Vec = [0, 0, 0];
  private yaw = DEFAULT_YAW;
  private pitch = DEFAULT_PITCH;
  private dist = 300;
  private data: SceneData = { segments: [], turtle: null };
  private colors: SheetColors;
  private raf = 0;
  private batches: Record<"ghost" | "grid" | "axes" | "scene" | "turtle", Batch>;
  private sceneKey: { arr: Segment[] | null; n: number } = { arr: null, n: -1 };
  private ghostKey: Segment[] | undefined | null = null;
  private gridKey = "";
  private view: Mat = new Float32Array(16);
  private proj: Mat = new Float32Array(16);
  private labels: Record<"x" | "y" | "z", HTMLElement>;
  private extent = 200;
  readonly scaleLabel = h("span", { class: "sheet-scale" });
