  /** null when WebGL works; otherwise the reason it cannot be used */
  static probe(): string | null {
    try {
      const c = document.createElement("canvas");
      const gl = c.getContext("webgl") || c.getContext("experimental-webgl");
      if (!gl) return "ta przeglądarka lub urządzenie nie udostępnia WebGL (akceleracja grafiki jest wyłączona albo niedostępna)";
      return null;
    } catch {
      return "utworzenie kontekstu WebGL nie powiodło się";
    }
  }

  constructor() {
    this.canvas = h("canvas", {
      class: "sheet-canvas",
      tabindex: "0",
      role: "img",
      "aria-label": "Rysunek żółwia w przestrzeni 3D. Strzałki obracają widok, shift ze strzałkami przesuwa, plus i minus zbliżają, zero dopasowuje.",
    });
    this.labels = { x: h("span", { class: "axis-label ax-x" }, "X"), y: h("span", { class: "axis-label ax-y" }, "Y"), z: h("span", { class: "axis-label ax-z" }, "Z") };
    this.el = h("div", { class: "view view-3d" }, this.canvas, this.labels.x, this.labels.y, this.labels.z, this.scaleLabel);
    const gl = (this.canvas.getContext("webgl", { antialias: true, preserveDrawingBuffer: true, alpha: false }) ||
