    this.batches = { ghost: mk(), grid: mk(), axes: mk(), scene: mk(), turtle: mk() };
    this.canvas.addEventListener("webglcontextlost", (e) => { e.preventDefault(); this.onLost?.(); });
    new ResizeObserver(() => this.resize()).observe(this.el);
    attachGestures(this.canvas, {
      drag: (dx, dy, pan) => (pan ? this.pan(dx, dy) : this.orbit(dx, dy)),
      pinch: (s, _cx, _cy, dx, dy) => { this.dolly(1 / s); this.pan(dx, dy); },
      wheel: (dy) => this.dolly(Math.exp(dy * 0.0015)),
      key: (e) => {
        const k = e.key;
        if (k.startsWith("Arrow")) {
          const dx = k === "ArrowLeft" ? -1 : k === "ArrowRight" ? 1 : 0;
          const dy = k === "ArrowUp" ? -1 : k === "ArrowDown" ? 1 : 0;
