  }

  refreshTheme() {
    this.colors = readSheetColors(this.el);
    this.gridKey = "";
    this.draw();
  }

  private resize() {
    const r = this.el.getBoundingClientRect();
    const w = Math.max(50, Math.round(r.width)), hh = Math.max(50, Math.round(r.height));
    this.dpr = Math.min(3, window.devicePixelRatio || 1);
    if (w === this.w && hh === this.hgt && this.canvas.width) return;
    this.w = w; this.hgt = hh;
    this.canvas.width = Math.round(w * this.dpr);
    this.canvas.height = Math.round(hh * this.dpr);
    this.canvas.style.width = w + "px";
    this.canvas.style.height = hh + "px";
    this.draw();
  }

  setScene(d: SceneData) {
    this.data = d;
    this.draw();
  }

  private bounds(): { c: Vec; r: number } {
    let lo: Vec = [0, 0, 0], hi: Vec = [0, 0, 0];
    const eat = (p: Vec) => { for (let i = 0; i < 3; i++) { lo[i] = Math.min(lo[i], p[i]); hi[i] = Math.max(hi[i], p[i]); } };
    for (const s of this.data.segments) { eat(s.from); eat(s.to); }
    for (const s of this.data.ghost ?? []) { eat(s.from); eat(s.to); }
