  private rgba(hex: string, a = 1): [number, number, number, number] {
    const [r, g, b] = hexToRgb(hex);
    return [r, g, b, a];
  }

  private buildStatic() {
    const { r } = this.bounds();
    let maxC = r * 2;
    for (const s of this.data.segments) for (const p of [s.from, s.to]) maxC = Math.max(maxC, Math.abs(p[0]), Math.abs(p[1]), Math.abs(p[2]));
    for (const s of this.data.ghost ?? []) for (const p of [s.from, s.to]) maxC = Math.max(maxC, Math.abs(p[0]), Math.abs(p[1]), Math.abs(p[2]));
    const extent = Math.max(100, niceCeil(maxC * 1.1));
    const key = `${extent}|${this.colors.grid}|${this.colors.axisX}`;
    if (key === this.gridKey) return;
    this.gridKey = key;
    this.extent = extent;
    const step = extent / 10;
    const lines: { a: Vec; b: Vec; rgba: [number, number, number, number]; w: number }[] = [];
    const gc = this.rgba(this.colors.grid, 1);
    for (let i = -10; i <= 10; i++) {
      if (i === 0) continue;
      lines.push({ a: [i * step, -extent, 0], b: [i * step, extent, 0], rgba: gc, w: 1 });
      lines.push({ a: [-extent, i * step, 0], b: [extent, i * step, 0], rgba: gc, w: 1 });
