    this.upload(this.batches.axes, lineData([
      { a: [0, 0, 0], b: [extent, 0, 0], rgba: this.rgba(this.colors.axisX), w: 2 },
      { a: [0, 0, 0], b: [0, extent, 0], rgba: this.rgba(this.colors.axisY), w: 2 },
      { a: [0, 0, 0], b: [0, 0, extent], rgba: this.rgba(this.colors.axisZ), w: 2 },
      { a: [-extent, 0, 0], b: [0, 0, 0], rgba: this.rgba(this.colors.axis, 1), w: 1 },
      { a: [0, -extent, 0], b: [0, 0, 0], rgba: this.rgba(this.colors.axis, 1), w: 1 },
    ]));
    this.scaleLabel.textContent = `siatka co ${step}`;
  }

  private buildScene() {
    const segs = this.data.segments;
    if (this.sceneKey.arr !== segs || this.sceneKey.n !== segs.length) {
      this.sceneKey = { arr: segs, n: segs.length };
      this.upload(this.batches.scene, lineData(segs.map((s) => ({ a: s.from, b: s.to, rgba: this.rgba(s.color), w: s.width }))));
