    for (const [k, p] of [["x", [this.extent, 0, 0]], ["y", [0, this.extent, 0]], ["z", [0, 0, this.extent]]] as const) {
      const [sx, sy, vis] = this.project(p as Vec);
      const el = this.labels[k];
      el.style.display = vis ? "" : "none";
      el.style.transform = `translate(${Math.round(sx + 4)}px, ${Math.round(sy - 8)}px)`;
    }
  }

  private drawBatch(b: Batch) {
    if (!b.count) return;
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, b.buf);
    const stride = FLOATS * 4;
    const attr = (name: string, size: number, off: number) => {
      gl.enableVertexAttribArray(this.loc[name]);
      gl.vertexAttribPointer(this.loc[name], size, gl.FLOAT, false, stride, off * 4);
