import type { Mode } from "../lang/types";
import { h } from "./dom";
import { View2D, type SceneData } from "./view2d";
import { View3D } from "./view3d";

/** Shows the drawing in 2D, or in 3D when WebGL works; otherwise a top-down view and the reason 3D is off. */
export class Viewport {
  readonly el: HTMLElement;
  readonly notice: HTMLElement;
  readonly v2 = new View2D();
  private v3: View3D | null = null;
  private v3Reason: string | null = null;
  private tried3 = false;
  private mode: Mode = "2d";
  private scene: SceneData = { segments: [], turtle: null };
  private stage = h("div", { class: "stage" });

  constructor() {
    this.notice = h("p", { class: "gl-notice", role: "status", hidden: true });
    this.el = h("div", { class: "viewport" }, this.notice, this.stage);
    this.stage.append(this.v2.el);
  }

  /** the reason 3D is unavailable, or null */
  get webglReason() {
    this.ensure3();
    return this.v3Reason;
  }

  private ensure3() {
    if (this.tried3) return;
    this.tried3 = true;
    const reason = View3D.probe();
    if (reason) { this.v3Reason = reason; return; }
    try {
      this.v3 = new View3D();
