      this.tool("Oddal", "zoomout", () => this.viewport.zoom(0.8)),
      this.tool("Resetuj kamerę", "home", () => this.viewport.resetView()),
      this.tool("Zapisz rysunek jako PNG", "image", () => this.opts.sheetExtras ? void 0 : void 0, "png"),
    );
    this.pngButton = tools.querySelector(".tool-png") as HTMLButtonElement;
    const sheetBar = h("div", { class: "sheet-bar" }, ...(opts.sheetExtras ?? []), tools);
    const sheetPane = h("section", { class: "pane pane-sheet", "aria-label": "Rysunek" }, sheetBar, this.viewport.el);
    this.el = h("div", { class: "bench" }, codePane, sheetPane);

    this.viewport.setMode(this.mode);
    this.unsub = this.controller.subscribe(() => this.refresh());
    this.applySpeed(false);
    this.refresh();
    this.runParse();
  }

  pngButton!: HTMLButtonElement;

  private tool(label: string, ic: string, onclick: () => void, name = "") {
    return h("button", { type: "button", class: "btn btn-icon tool-" + (name || ic), onclick, "aria-label": label, title: label }, icon(ic));
  }

  destroy() {
    this.controller.reset();
    this.unsub();
  }

  getSource() { return this.source; }
  getMode() { return this.mode; }

  setMode(mode: Mode, source: string) {
    this.controller.reset();
    this.mode = mode;
    this.source = source;
    this.editor.setValue(source);
    this.viewport.setMode(mode);
    this.el.dataset.mode = mode;
    this.runParse();
    this.refresh();
    requestAnimationFrame(() => this.viewport.fit());
  }

  setSource(source: string) {
    this.source = source;
    this.editor.setValue(source);
    this.controller.reset();
    this.runParse();
  }

  setGhost(ghost: Segment[] | undefined) {
    this.ghost = ghost;
    this.refresh();
  }

  run() {
    this.controller.run();
    this.viewport.fit();
  }

  /** immediate, unanimated run used by tests/open(): the drawing is on screen and fitted when this returns */
  runInstant() {
    this.controller.runToEnd();
    this.viewport.fit();
  }

  reset() {
    this.controller.reset();
    this.viewport.fit();
  }

  private togglePause() {
    const s = this.controller.snapshot().state;
    if (s === "running") this.controller.pause();
    else if (s === "paused") this.controller.resume();
  }

  private applySpeed(persist: boolean) {
    const level = Number(this.speed.value);
    const v = SPEEDS[level] ?? 100;
    this.controller.setSpeed(v);
    this.speedOut.textContent = speedLabel(v);
    this.speed.setAttribute("aria-valuetext", speedLabel(v));
    if (persist) this.opts.onSpeed(level);
  }

  private scheduleParse() {
    clearTimeout(this.parseTimer);
    this.parseTimer = window.setTimeout(() => { this.runParse(); this.refresh(); }, 250);
  }

  /** checks the program as a whole without drawing, to mark parse errors while typing */
  private runParse() {
    clearTimeout(this.parseTimer);
    try {
      parse(this.source, this.mode);
      this.liveError = null;
    } catch (e) {
      if (!(e instanceof LogoError)) throw e;
      this.liveError = e.info();
    }
  }

  private goToError() {
    const e = this.shownError();
    if (e) this.editor.goTo(e.line, e.column);
  }

  private shownError(): LogoErrorInfo | null {
    const s = this.controller.snapshot();
    if (s.error && !s.stale) return s.error;
    return this.liveError;
  }

  private refresh() {
    const s: Snapshot = this.controller.snapshot();
    this.viewport.setScene({
      segments: s.segments,
      turtle: s.state === "idle" && s.segments.length === 0 ? { ...s.turtle } : s.turtle,
      ghost: this.ghost,
    });
    const running = s.state === "running", paused = s.state === "paused";
    this.btnPause.disabled = !(running || paused);
    const lbl = this.btnPause.querySelector(".btn-label")!;
    lbl.textContent = paused ? "Wznów" : "Pauza";
    this.btnPause.replaceChild(icon(paused ? "play" : "pause"), this.btnPause.querySelector("svg")!);
    this.el.dataset.state = s.state;
    this.editor.setActive(running || paused ? s.current?.line ?? null : null);
    const err = this.shownError();
    this.editor.setError(err);
    if (err) {
      this.problem.hidden = false;
      this.problem.replaceChildren(icon("x", 16), h("span", null, `Wiersz ${err.line}, kolumna ${err.column}: ${err.message}`));
    } else {
      this.problem.hidden = true;
    }
    const n = s.segments.length;
    const count = `${n} ${n === 1 ? "odcinek" : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) ? "odcinki" : "odcinków"}`;
    let text: string;
    if (s.stale) text = "Program zmieniony: rysunek jest nieaktualny. Uruchom ponownie.";
    else if (s.state === "idle") text = this.liveError ? "Popraw błąd, aby uruchomić program." : "Gotowy. Uruchom program lub wykonuj go krok po kroku.";
    else if (s.state === "running") text = `Wykonuję… ${count}`;
    else if (s.state === "paused") text = `Pauza${s.current ? ` po wierszu ${s.current.line}` : ""}. ${count}`;
    else if (s.state === "done") text = `Koniec programu. ${count}`;
    else text = s.error && s.segments.length ? `Program zatrzymany błędem. Zachowano ${count}.` : "Program nie został wykonany: popraw błąd.";
    this.status.textContent = text;
  }

  /** returns true when the key was a workbench shortcut */
  handleKey(e: KeyboardEvent): boolean {
    const mod = e.ctrlKey || e.metaKey;
    if (!mod) return false;
    if (e.key === "Enter" && !e.shiftKey) { this.run(); return true; }
    if (e.key === "Enter" && e.shiftKey) { this.controller.step(); return true; }
    if (e.key === " " || e.code === "Space") { this.togglePause(); return true; }
    if (e.key === "Backspace" && e.shiftKey) { this.reset(); return true; }
    return false;
  }
}
