import type { Segment } from "../lang/types";

/** a small drawing of a program's result: flat for 2D, an isometric view for 3D */
export function drawThumb(canvas: HTMLCanvasElement, segments: Segment[], mode: "2d" | "3d", ink: { bg: string }) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const W = canvas.width, H = canvas.height;
  ctx.fillStyle = ink.bg;
  ctx.fillRect(0, 0, W, H);
  const P = (p: [number, number, number]): [number, number] =>
    mode === "2d" ? [p[0], -p[1]] : [(p[0] - p[1]) * 0.866, -p[2] + (p[0] + p[1]) * 0.5];
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const s of segments) for (const q of [s.from, s.to]) {
    const [x, y] = P(q);
    minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }
  if (!Number.isFinite(minX)) return;
  const pad = 8;
  const k = Math.min((W - 2 * pad) / Math.max(maxX - minX, 1), (H - 2 * pad) / Math.max(maxY - minY, 1));
  const ox = (W - (maxX - minX) * k) / 2 - minX * k;
  const oy = (H - (maxY - minY) * k) / 2 - minY * k;
  ctx.lineCap = "round";
  for (const s of segments) {
    const [x1, y1] = P(s.from), [x2, y2] = P(s.to);
    ctx.strokeStyle = s.color;
    ctx.lineWidth = Math.max(1, Math.min(2, s.width * 0.6));
    ctx.beginPath();
    ctx.moveTo(x1 * k + ox, y1 * k + oy);
    ctx.lineTo(x2 * k + ox, y2 * k + oy);
    ctx.stroke();
  }
}
