import { h, icon } from "./dom";

let region: HTMLElement | null = null;

export function mountToasts(el: HTMLElement) { region = el; }

/** a transient message; an optional action (e.g. "Cofnij") keeps it open longer */
export function toast(message: string, action?: { label: string; run: () => void }, ms = action ? 9000 : 4500) {
  if (!region) return;
  const item = h("div", { class: "toast" }, h("span", { class: "toast-text" }, message));
  let timer = 0;
  const close = () => { clearTimeout(timer); item.remove(); };
  if (action) {
    item.append(h("button", { type: "button", class: "btn btn-quiet", onclick: () => { action.run(); close(); } }, action.label));
  }
  item.append(h("button", { type: "button", class: "btn btn-icon btn-quiet", "aria-label": "Zamknij komunikat", onclick: close }, icon("x", 16)));
  region.append(item);
  timer = window.setTimeout(close, ms);
}

export interface DialogHandle { dialog: HTMLDialogElement; close(): void }

/** a modal dialog with a title and a close button; Escape and the backdrop close it */
export function openDialog(title: string, body: Node, className = ""): DialogHandle {
  const dialog = h("dialog", { class: "dlg " + className, "aria-labelledby": "dlg-title" });
  const close = () => { if (dialog.open) dialog.close(); dialog.remove(); };
  const head = h("header", { class: "dlg-head" },
    h("h2", { id: "dlg-title" }, title),
    h("button", { type: "button", class: "btn btn-icon btn-quiet", "aria-label": "Zamknij okno", onclick: close }, icon("x")));
  dialog.append(head, h("div", { class: "dlg-body" }, body));
  dialog.addEventListener("click", (e) => { if (e.target === dialog) close(); });
  dialog.addEventListener("close", () => dialog.remove());
  document.body.append(dialog);
  if (typeof dialog.showModal === "function") dialog.showModal(); else dialog.setAttribute("open", "");
  return { dialog, close };
}

/** a button that toggles a small panel; closes on Escape, outside click and when focus leaves */
export function menuButton(label: string, ic: string, panel: HTMLElement, cls = ""): HTMLElement {
  panel.hidden = true;
  panel.classList.add("menu-panel");
  const btn = h("button", { type: "button", class: "btn " + cls, "aria-expanded": "false", "aria-haspopup": "true" }, icon(ic), h("span", { class: "btn-label" }, label), icon("chevron", 16));
  const wrap = h("div", { class: "menu" }, btn, panel);
  const set = (open: boolean, focusBtn = false) => {
    panel.hidden = !open;
    btn.setAttribute("aria-expanded", String(open));
    if (!open && focusBtn) btn.focus();
  };
  btn.addEventListener("click", () => set(panel.hidden));
  wrap.addEventListener("keydown", (e) => { if (e.key === "Escape" && !panel.hidden) { e.stopPropagation(); set(false, true); } });
  wrap.addEventListener("focusout", (e) => {
    const next = e.relatedTarget as Node | null;
    if (next && !wrap.contains(next)) set(false);
  });
  document.addEventListener("pointerdown", (e) => { if (!wrap.contains(e.target as Node)) set(false); });
  panel.addEventListener("click", (e) => { if ((e.target as HTMLElement).closest("button, a")) set(false); });
  return wrap;
}
