/** The main workspace: one draft per mode, switched with the 2D / 3D control. */
export class StudioPage {
  readonly el: HTMLElement;
  readonly bench: Workbench;
  private radios: Record<Mode, HTMLInputElement>;

  constructor(private deps: StudioDeps) {
    const ws = deps.workspace;
    const mk = (mode: Mode, label: string, checked: boolean) =>
      h("input", { type: "radio", name: "tryb", value: mode, checked, onchange: () => this.switchMode(mode), "aria-label": label });
    this.radios = { "2d": mk("2d", "Tryb 2D, płaszczyzna", ws.mode === "2d"), "3d": mk("3d", "Tryb 3D, przestrzeń", ws.mode === "3d") };
    const seg = h("fieldset", { class: "seg" },
      h("legend", { class: "sr-only" }, "Tryb rysowania"),
      h("label", null, this.radios["2d"], h("span", null, "2D")),
      h("label", null, this.radios["3d"], h("span", null, "3D")));
    this.bench = new Workbench({
      mode: ws.mode,
      source: ws.draft(ws.mode),
      label: "Program Logo",
      speedLevel: deps.speedLevel,
      onSource: (t) => ws.setDraft(this.bench.getMode(), t),
      onSpeed: deps.onSpeed,
      sheetExtras: [seg],
    });
    this.bench.el.dataset.mode = ws.mode;
    this.el = h("div", { class: "page page-studio" }, this.bench.el);
  }

  private switchMode(mode: Mode) {
    this.deps.workspace.setMode(mode);
    this.bench.setMode(mode, this.deps.workspace.draft(mode));
  }

  /** shows the active workspace mode and draft (after the workspace was changed from outside) */
  syncFromWorkspace() {
    const ws = this.deps.workspace;
    this.radios[ws.mode].checked = true;
    this.bench.setMode(ws.mode, ws.draft(ws.mode));
  }

  /** the Wi-Fi-less equivalent of pasting `text` into the editor */
  show() { requestAnimationFrame(() => this.bench.viewport.fit()); }
}
