import { CHALLENGES, checkChallenge, type Challenge, type ChallengeProgress } from "../../core/challenges";
import { run } from "../../lang";
import { h, icon } from "../dom";
import { Workbench } from "../workbench";

export interface ChallengeDeps {
  progress: ChallengeProgress;
  speedLevel: number;
  onSpeed(level: number): void;
  navigate(route: string): void;
}

/** Practice tasks: the target is shown as a faint guide under the drawing, and a check compares the ink. */
export class ChallengesPage {
  readonly el: HTMLElement;
  bench: Workbench | null = null;
  private current: Challenge;
  private list: HTMLElement;
  private head: HTMLElement;
  private result: HTMLElement;
  private summary: HTMLElement;
  private showTarget = true;
  private guideBox: HTMLInputElement;
  private benchHost = h("div", { class: "bench-host" });

  constructor(private deps: ChallengeDeps) {
    this.current = CHALLENGES[0];
    this.list = h("ol", { class: "ch-list" });
    this.summary = h("p", { class: "ch-summary" });
    this.head = h("div", { class: "ch-head" });
    this.result = h("div", { class: "ch-result", role: "status", "aria-live": "polite" });
    this.guideBox = h("input", { type: "checkbox", checked: true, onchange: () => { this.showTarget = this.guideBox.checked; this.applyGhost(); } });
    const nav = h("nav", { class: "ch-nav", "aria-label": "Lista wyzwań" }, h("h2", { class: "ch-nav-title" }, "Wyzwania"), this.summary, this.list);
    const main = h("div", { class: "ch-main" }, this.head, this.benchHost, this.result);
    this.el = h("div", { class: "page page-challenges" }, nav, main);
    this.renderList();
  }

  private ensureBench(c: Challenge) {
    if (this.bench) return this.bench;
    const checkBtn = h("button", { type: "button", class: "btn btn-primary", onclick: () => this.check() }, icon("check"), h("span", { class: "btn-label" }, "Sprawdź"));
    const guide = h("label", { class: "check" }, this.guideBox, h("span", null, "Pokaż wzór"));
    this.bench = new Workbench({
      mode: c.mode,
      source: this.initialSource(c),
      label: "Rozwiązanie wyzwania",
      speedLevel: this.deps.speedLevel,
      onSource: (t) => this.deps.progress.saveDraft(this.current.id, t),
      onSpeed: this.deps.onSpeed,
      ghost: this.ghostFor(c),
      sheetExtras: [checkBtn, guide],
    });
    this.benchHost.replaceChildren(this.bench.el);
    return this.bench;
  }

  private initialSource(c: Challenge) {
    return this.deps.progress.source(c.id) ?? c.starter;
  }

  private ghostFor(c: Challenge) {
    return this.showTarget ? run(c.solution, c.mode).segments : undefined;
  }

  private applyGhost() {
    this.bench?.setGhost(this.ghostFor(this.current));
  }

  open(id: string | undefined) {
    const c = CHALLENGES.find((x) => x.id === id) ?? this.current;
    this.current = c;
    const bench = this.ensureBench(c);
    if (bench.getMode() !== c.mode || bench.getSource() !== this.initialSource(c) || this.head.dataset.id !== c.id) {
      bench.setMode(c.mode, this.initialSource(c));
    }
    bench.setGhost(this.ghostFor(c));
    this.head.dataset.id = c.id;
    const idx = CHALLENGES.indexOf(c);
    const solved = this.deps.progress.isSolved(c.id);
    this.head.replaceChildren(
      h("h2", { class: "ch-title" }, `${idx + 1}. ${c.title}`, h("span", { class: "badge" }, c.mode.toUpperCase()), solved ? h("span", { class: "badge badge-ok" }, icon("check", 14), "Rozwiązane") : null),
      h("p", { class: "ch-task" }, c.task),
      h("details", { class: "ch-hint" }, h("summary", null, "Podpowiedź"), h("p", null, c.hint)),
    );
    const last = this.deps.progress.lastReason(c.id);
    this.result.replaceChildren(...(last ? [this.resultNode(solved && last === "Zgadza się z wzorem.", last)] : []));
    this.renderList();
    bench.viewport.fit();
  }

  private resultNode(pass: boolean, reason: string) {
    const idx = CHALLENGES.indexOf(this.current);
    const next = CHALLENGES[idx + 1];
    return h("div", { class: "result " + (pass ? "is-pass" : "is-fail") },
      icon(pass ? "check" : "x"),
      h("div", { class: "result-text" },
        h("strong", null, pass ? "Zaliczone!" : "Jeszcze nie."),
        h("span", null, " " + reason),
        pass && next ? h("button", { type: "button", class: "btn", onclick: () => this.deps.navigate("#/wyzwania/" + next.id) }, "Następne: " + next.title) : null));
  }

  check() {
    if (!this.bench) return;
    const source = this.bench.getSource();
    const c = this.current;
    const r = checkChallenge(c, source);
    this.deps.progress.record(c.id, r, source);
    this.bench.runInstant();
    this.result.replaceChildren(this.resultNode(r.pass, r.reason));
    this.renderList();
    this.open(c.id === this.current.id ? c.id : undefined);
    this.result.replaceChildren(this.resultNode(r.pass, r.reason));
  }

  private renderList() {
    const p = this.deps.progress;
    this.summary.textContent = `Rozwiązane: ${p.solvedCount()} z ${CHALLENGES.length}`;
    this.list.replaceChildren(...CHALLENGES.map((c) => {
      const solved = p.isSolved(c.id);
      return h("li", null, h("a", {
        href: "#/wyzwania/" + c.id,
        class: "ch-item" + (c.id === this.current.id ? " is-current" : ""),
        "aria-current": c.id === this.current.id ? "page" : null,
      }, solved ? icon("check", 16) : h("span", { class: "ch-dot", "aria-hidden": "true" }), h("span", { class: "ch-item-title" }, c.title), h("span", { class: "badge" }, c.mode.toUpperCase()), solved ? h("span", { class: "sr-only" }, "(rozwiązane)") : null));
    }));
  }
}
