    else {
      body.append(h("ul", { class: "backups" }, ...backups.map((b) => h("li", null,
        h("span", { class: "backup-meta" }, h("span", { class: "badge" }, b.mode.toUpperCase()), " ", new Date(b.at).toLocaleString("pl-PL")),
        h("code", { class: "backup-snippet" }, b.source.trim().split("\n")[0].slice(0, 60) || "(pusty)"),
        h("button", { type: "button", class: "btn", onclick: () => {
          handle.close();
          afterLoad(workspace.restoreBackup(b.id), { note: "Przywrócono kopię szkicu." });
        } }, icon("undo"), h("span", { class: "btn-label" }, "Przywróć"))))));
    }
    const d = openDialog("Przykłady", body, "dlg-wide");
    handle.close = d.close;
  }

  function openShortcuts() {
    openDialog("Skróty klawiszowe", h("div", null,
      h("p", { class: "dlg-lead" }, "Na komputerze Mac zamiast Ctrl użyj ⌘."),
      h("table", { class: "table" },
        h("caption", { class: "sr-only" }, "Skróty klawiszowe"),
        h("thead", null, h("tr", null, h("th", { scope: "col" }, "Skrót"), h("th", { scope: "col" }, "Działanie"))),
        h("tbody", null, ...SHORTCUTS.map(([k, d]) => h("tr", null, h("td", null, h("kbd", null, k)), h("td", null, d)))))));
  }

  // ---- sharing and files
  function current(): { source: string; mode: Mode } {
    const b = activeBench() ?? studio.bench;
    return { source: b.getSource(), mode: b.getMode() };
  }

  async function copyLink() {
    const { source, mode } = current();
    const url = location.href.split("#")[0] + encodeShare(source, mode);
    try {
      await navigator.clipboard.writeText(url);
      toast(url.length > 8000 ? "Skopiowano link, ale jest bardzo długi; niektóre komunikatory mogą go obciąć." : "Skopiowano link do programu.");
    } catch {
      const input = h("input", { type: "text", readonly: true, value: url, class: "link-box", "aria-label": "Link do programu" });
      const d = openDialog("Link do programu", h("div", null, h("p", { class: "dlg-lead" }, "Nie udało się skopiować automatycznie. Zaznacz link i skopiuj go ręcznie."), input));
      input.focus(); input.select();
      void d;
    }
  }

  function downloadProgram() {
    const { source, mode } = current();
    const f = toLogoFile(source, mode);
    downloadBlob(new Blob([f.content], { type: f.type }), f.filename);
  }

  async function openFile() {
    const file = fileInput.files?.[0];
    fileInput.value = "";
    if (!file) return;
    try {
      const text = fromLogoFile(await file.text());
      loadProgram(text, guessMode(text, workspace.mode), { run: false, note: `Otwarto plik „${file.name}”.` });
    } catch {
      toast("Nie udało się odczytać pliku.");
    }
  }

  // ---- keyboard
  document.addEventListener("keydown", (e) => {
    if (document.querySelector("dialog[open]")) return;
    if (route.page === "polecenia") return;
    const b = activeBench();
    if (b && b.handleKey(e)) e.preventDefault();
  });

  window.addEventListener("hashchange", onHash);
  onHash();

  // ---- testing hook
  const api = {
    version: VERSION,
    run(source: string, mode: Mode): RunResult { return run(source, mode); },
    async open(source: string, mode: Mode): Promise<RunResult> {
      workspace.loadText(source, mode);
      if (route.page !== "pracownia") navigate("#/pracownia"); else show(route);
      studio.syncFromWorkspace();
      await nextFrame();
      studio.bench.runInstant();
      await nextFrame();
      studio.bench.viewport.fit();
      await nextFrame();
      return run(source, mode);
    },
  };
  return api;
}
