.ln.is-error { background: var(--error-line); box-shadow: -12px 0 0 var(--error-line), 40px 0 0 var(--error-line); }
.ed-ta {
  position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 8px 12px; resize: none; border: 0; outline: none;
  background: transparent; color: transparent; caret-color: var(--ink);
  font: inherit; white-space: pre; overflow: auto; tab-size: 2; overscroll-behavior: contain;
}
.ed-ta::selection { background: var(--select); color: transparent; }
.tk-cmd { color: var(--tk-cmd); font-weight: 600; }
.tk-num { color: var(--tk-num); }
.tk-str { color: var(--tk-str); }
.tk-com { color: var(--tk-com); font-style: italic; }
.tk-def { color: var(--tk-def); font-weight: 600; }
.tk-val { color: var(--tk-val); font-weight: 600; }
.tk-proc { color: var(--tk-proc); font-weight: 600; }
.tk-name { color: var(--ink); }
.tk-br, .tk-op { color: var(--muted); }
.tk-err { text-decoration: underline wavy var(--danger); text-decoration-thickness: 1.5px; text-underline-offset: 3px; background: rgb(179 50 31 / 0.16); border-radius: 2px; }

/* ---------- dialogs, toasts ---------- */
dialog.dlg {
  width: min(560px, calc(100vw - 24px)); max-height: min(86dvh, 760px); padding: 0; overflow: hidden;
  border: 1px solid var(--line-strong); border-radius: 12px; background: var(--panel); color: var(--ink);
  box-shadow: 0 18px 48px rgb(0 0 0 / 0.3), 0 3px 8px rgb(0 0 0 / 0.15);
}
dialog.dlg[open] { display: flex; flex-direction: column; }
dialog.dlg-wide { width: min(900px, calc(100vw - 24px)); }
dialog.dlg::backdrop { background: rgb(8 16 12 / 0.55); }
.dlg-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 12px 8px 20px; }
.dlg-head h2 { font-size: 20px; }
.dlg-body { overflow: auto; padding: 0 20px 20px; }
.dlg-lead { color: var(--muted); font-size: 15px; }
.link-box { width: 100%; min-height: 40px; padding: 0 10px; font: 14px var(--mono); color: var(--ink); background: var(--panel-2); border: 1px solid var(--line-strong); border-radius: var(--r); }

.toasts { position: fixed; z-index: 60; left: 0; right: 0; bottom: 16px; display: flex; flex-direction: column; align-items: center; gap: 8px; pointer-events: none; padding: 0 12px; }
.toast {
  pointer-events: auto; display: flex; align-items: center; gap: 4px; max-width: min(560px, 100%); padding: 6px 6px 6px 16px;
  background: var(--ink); color: var(--bg); border-radius: 10px; box-shadow: 0 8px 24px rgb(0 0 0 / 0.3), 0 1px 3px rgb(0 0 0 / 0.2); font-size: 14px;
  animation: toast-in 160ms cubic-bezier(0.16, 1, 0.3, 1);
}
.toast-text { flex: 1; padding: 6px 8px 6px 0; }
.toast .btn-quiet { color: var(--bg); }
.toast .btn-quiet:hover:not(:disabled) { background: rgb(128 128 128 / 0.3); }
.toast :focus-visible { outline-color: var(--bg); }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

/* ---------- examples ---------- */
.ex-group { font-size: 15px; margin: 16px 0 8px; color: var(--muted); font-weight: 600; }
.ex-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(172px, 1fr)); gap: 12px; }
.ex-card { display: flex; flex-direction: column; gap: 4px; width: 100%; height: 100%; padding: 8px; text-align: left; border: 1px solid var(--line-strong); border-radius: var(--r); background: var(--panel); color: inherit; font: inherit; cursor: pointer; transition: background-color 120ms ease-out, border-color 120ms ease-out; }
.ex-card:hover { background: var(--panel-2); border-color: var(--accent); }
.ex-thumb { width: 100%; height: auto; border-radius: 5px; border: 1px solid var(--line); }
.ex-title { font-weight: 700; margin-top: 4px; }
.ex-blurb { font-size: 13px; color: var(--muted); line-height: 1.35; }
.backups { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.backups li { display: grid; grid-template-columns: 1fr auto; gap: 4px 12px; align-items: center; padding: 8px 12px; border: 1px solid var(--line); border-radius: var(--r); }
.backup-meta { font-size: 13px; color: var(--muted); }
.backup-snippet { grid-column: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; }
.backups .btn { grid-column: 2; grid-row: 1 / span 2; }

/* ---------- challenges ---------- */
.page-challenges { display: grid; grid-template-columns: 264px minmax(0, 1fr); min-height: 0; }
.ch-nav { display: flex; flex-direction: column; gap: 4px; padding: 16px 12px 16px 16px; overflow: auto; border-right: 1px solid var(--line); background: var(--panel); }
.ch-nav-title { font-size: 18px; }
.ch-summary { font-size: 14px; color: var(--muted); margin: 0 0 8px; }
.ch-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.ch-item { display: flex; align-items: center; gap: 10px; min-height: 42px; padding: 0 10px; border-radius: var(--r); color: var(--ink); text-decoration: none; font-size: 15px; }
.ch-item:hover { background: var(--panel-2); }
.ch-item.is-current { background: var(--accent-soft); font-weight: 600; }
.ch-item .icon { color: var(--accent); }
.ch-dot { width: 8px; height: 8px; margin: 0 6px; border-radius: 50%; border: 1.5px solid var(--line-strong); flex: none; }
.ch-item-title { flex: 1; }
.ch-item .badge { margin: 0; }
.ch-main { display: flex; flex-direction: column; min-height: 0; min-width: 0; }
.ch-head { padding: 14px 16px 0; }
.ch-title { font-size: 22px; }
.ch-task { margin: 6px 0 4px; max-width: 70ch; }
.ch-hint { margin: 0 0 8px; font-size: 14px; }
.ch-hint summary { cursor: pointer; color: var(--accent); font-weight: 600; min-height: 28px; display: inline-flex; align-items: center; }
.ch-hint p { margin: 4px 0 0; color: var(--muted); }
.bench-host { flex: 1; min-height: 0; }
.ch-result { padding: 0 16px 12px; }
.ch-result:empty { padding: 0; }
.result { display: flex; align-items: flex-start; gap: 10px; padding: 10px 14px; border-radius: var(--r); border: 1px solid var(--line-strong); }
.result.is-pass { background: var(--ok-soft); border-color: var(--accent); }
