.result.is-fail { background: var(--danger-soft); border-color: var(--danger); }
.result.is-fail > .icon { color: var(--danger); }
.result-text { display: flex; flex-wrap: wrap; gap: 4px 8px; align-items: center; }
.result-text .btn { min-height: 34px; }

/* ---------- reference ---------- */
.page-reference { display: grid; grid-template-columns: 232px minmax(0, 1fr); gap: 40px; width: 100%; max-width: 1120px; margin: 0 auto; padding: 28px 20px 64px; align-items: start; }
.toc { position: sticky; top: 16px; max-height: calc(100dvh - 32px); overflow: auto; font-size: 15px; }
.toc-title { font-size: 14px; color: var(--muted); font-weight: 600; margin-bottom: 8px; }
.toc ul { list-style: none; margin: 0; padding: 0; }
.toc a { display: block; padding: 6px 10px; border-radius: 6px; color: var(--ink); text-decoration: none; }
.toc a:hover { background: var(--panel-2); }
.ref { max-width: 76ch; min-width: 0; }
.ref h1 { font-size: 30px; margin-bottom: 20px; letter-spacing: -0.01em; }
.ref-section { margin-top: 40px; scroll-margin-top: 16px; }
.ref-section h2 { font-size: 24px; margin-bottom: 12px; padding-top: 12px; border-top: 1px solid var(--line); }
.ref-group h3 { font-size: 18px; margin: 28px 0 4px; color: var(--accent); }
.cmd { padding: 16px 0; border-bottom: 1px solid var(--line); }
.cmd-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 16px; font-size: 18px; margin-bottom: 6px; }
.cmd-head code { font-size: 1em; font-weight: 700; background: var(--accent-soft); color: var(--ink); }
.cmd-en { font-size: 13px; color: var(--muted); font-weight: 400; }
.cmd-en code { font-size: 0.95em; font-weight: 500; background: var(--panel-2); }
.cmd-syntax { margin: 0 0 6px; }
.example { margin: 12px 0; }
.example figcaption { font-size: 13px; color: var(--muted); font-weight: 600; margin-bottom: 4px; }
.example .badge { margin-left: 6px; }
pre.code { margin: 0 0 8px; padding: 10px 14px; overflow: auto; border: 1px solid var(--line); border-radius: var(--r); background: var(--panel); font: 14px/22px var(--mono); white-space: pre; }
.cl { display: block; height: 22px; }
.table { width: 100%; border-collapse: collapse; font-size: 15px; }
.table th { text-align: left; font-size: 13px; color: var(--muted); padding: 6px 10px; border-bottom: 2px solid var(--line-strong); }
.table td { padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }

/* ---------- small screens ---------- */
@media (max-width: 860px) {
  body[data-route="pracownia"], body[data-route="wyzwania"] { height: auto; min-height: 100dvh; overflow: auto; }
  .top { gap: 6px 12px; padding: 8px 12px; }
  .nav { order: 3; width: 100%; }
  .nav-link { flex: 1; justify-content: center; padding: 0 8px; }
  .actions { gap: 6px; }
  .bench { display: flex; flex-direction: column; height: auto; }
  .pane-sheet { order: 1; padding: 8px 12px 0; }
  .pane-code { order: 2; padding: 4px 12px 12px; }
  .viewport { flex: none; height: clamp(240px, 42dvh, 440px); }
  .ed { min-height: 280px; flex: none; height: 44dvh; }
  .page-challenges { display: flex; flex-direction: column; }
  .ch-nav { flex-direction: row; flex-wrap: wrap; align-items: center; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--line); overflow: visible; }
  .ch-nav-title { display: none; }
  .ch-summary { margin: 0 12px 0 0; }
  .ch-list { flex-direction: row; overflow-x: auto; padding-bottom: 4px; max-width: 100%; }
  .ch-item { white-space: nowrap; }
  .ch-item .badge { display: none; }
  .bench-host { flex: none; }
  .page-reference { grid-template-columns: 1fr; gap: 16px; padding: 16px 14px 48px; }
  .toc { position: static; max-height: none; }
  .toc ul { display: flex; flex-wrap: wrap; gap: 2px 4px; }
  .ed, .ed-ta { font-size: 16px; }
}
@media (max-width: 640px) {
  .actions .btn-label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
  .actions .btn:not(.btn-icon) { padding: 0 10px; }
  .actions .menu .btn .icon:last-child { display: none; }
  .actions #examples-btn .btn-label { position: static; width: auto; height: auto; clip: auto; }
  .brand-name { font-size: 18px; }
  .runbar .btn:not(.btn-primary) .btn-label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
  .runbar .btn:not(.btn-primary) { width: 44px; padding: 0; }
  .speed { margin-left: 0; width: 100%; }
  .speed input { flex: 1; width: auto; }
  .speed-out { text-align: right; }
}
@media (pointer: coarse) {
  .btn { min-height: 44px; }
  .btn-icon { width: 44px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
}
