.check input { width: 18px; height: 18px; accent-color: var(--accent); }

.menu { position: relative; }
.menu-panel {
  position: absolute; right: 0; top: calc(100% + 6px); z-index: 30; min-width: 270px; padding: 6px;
  background: var(--panel); border: 1px solid var(--line-strong); border-radius: var(--r);
  box-shadow: 0 10px 28px rgb(0 0 0 / 0.18), 0 2px 4px rgb(0 0 0 / 0.1);
}
.menu-item { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 42px; padding: 0 12px; border: 0; border-radius: 6px; background: none; color: inherit; font: 500 15px var(--sans); text-align: left; cursor: pointer; }
.menu-item:hover { background: var(--panel-2); }

/* ---------- main layout ---------- */
main { flex: 1; min-height: 0; display: flex; flex-direction: column; }
main:focus { outline: none; }
.page { flex: 1; min-height: 0; }
body[data-route="pracownia"], body[data-route="wyzwania"] { height: 100dvh; overflow: hidden; }
body[data-route="polecenia"] main { overflow: visible; }

/* ---------- workbench ---------- */
.bench { height: 100%; display: grid; grid-template-columns: minmax(340px, 5fr) 7fr; min-height: 0; }
.pane { display: flex; flex-direction: column; min-height: 0; min-width: 0; }
.pane-code { padding: 12px 8px 12px 16px; gap: 8px; }
.pane-sheet { padding: 12px 16px 0 8px; }
.runbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.speed { display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 13px; color: var(--muted); }
.speed input { width: 96px; accent-color: var(--accent); height: 40px; }
.speed-out { min-width: 8.5em; font: 12px var(--mono); color: var(--muted); }
.statusbar { display: flex; flex-direction: column; gap: 6px; min-height: 28px; }
.status-text { font-size: 14px; color: var(--muted); }
.problem {
  display: flex; align-items: flex-start; gap: 8px; width: 100%; padding: 8px 12px; text-align: left;
  border: 1px solid var(--danger); border-radius: var(--r); background: var(--danger-soft); color: var(--ink); font: 500 14px/1.4 var(--sans); cursor: pointer;
}
.problem .icon { color: var(--danger); margin-top: 1px; }

.sheet-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding-bottom: 8px; min-height: 48px; }
.tools { display: inline-flex; gap: 4px; margin-left: auto; }
.viewport { position: relative; flex: 1; min-height: 0; margin-bottom: 12px; border: 1px solid var(--line-strong); border-radius: var(--r); overflow: hidden; background: var(--sheet); }
.stage, .view { position: absolute; inset: 0; }
.sheet-canvas { display: block; touch-action: none; cursor: grab; }
.sheet-canvas.is-dragging { cursor: grabbing; }
.sheet-canvas:focus-visible { outline-offset: -4px; }
.sheet-scale { position: absolute; right: 10px; bottom: 6px; font: 12px var(--mono); color: var(--sheet-muted); pointer-events: none; }
.axis-label { position: absolute; left: 0; top: 0; font: 700 13px var(--mono); pointer-events: none; }
.ax-x { color: var(--axis-x); } .ax-y { color: var(--axis-y); } .ax-z { color: var(--axis-z); }
.gl-notice { position: absolute; z-index: 2; left: 8px; right: 8px; top: 8px; margin: 0; padding: 8px 12px; font-size: 14px; background: var(--panel); border: 1px solid var(--warm); border-radius: var(--r); color: var(--ink); }

/* ---------- editor ---------- */
.ed {
  flex: 1; min-height: 160px; display: flex; overflow: hidden;
  border: 1px solid var(--line-strong); border-radius: var(--r); background: var(--panel);
  font: 14px/22px var(--mono);
}
.ed:focus-within { outline: 2px solid var(--focus); outline-offset: 1px; }
.ed-gutter { flex: none; min-width: 3.4em; overflow: hidden; background: var(--panel-2); border-right: 1px solid var(--line); color: var(--muted); text-align: right; user-select: none; }
.ed-gutter-inner { padding: 8px 8px; }
.gn { height: 22px; position: relative; font-variant-numeric: tabular-nums; }
.gn.is-active { color: var(--ink); font-weight: 700; }
.gn.is-error { color: var(--danger); font-weight: 700; }
.gn.is-error::before { content: "!"; position: absolute; left: -2px; font-weight: 800; }
.gn.is-active:not(.is-error)::before { content: "›"; position: absolute; left: -2px; color: var(--accent); font-weight: 800; }
.ed-body { position: relative; flex: 1; min-width: 0; }
.ed-under { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.ed-under-inner { width: max-content; min-width: 100%; padding: 8px 12px; will-change: transform; }
.ln { height: 22px; white-space: pre; tab-size: 2; }
.ln.is-active { background: var(--active-line); box-shadow: -12px 0 0 var(--active-line), 40px 0 0 var(--active-line); }
.ln.is-error { background: var(--error-line); box-shadow: -12px 0 0 var(--error-line), 40px 0 0 var(--error-line); }
.ed-ta {
  position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 8px 12px; resize: none; border: 0; outline: none;
  background: transparent; color: transparent; caret-color: var(--ink);
  font: inherit; white-space: pre; overflow: auto; tab-size: 2; overscroll-behavior: contain;
}
.ed-ta::selection { background: var(--select); color: transparent; }
.tk-cmd { color: var(--tk-cmd); font-weight: 600; }
.tk-num { color: var(--tk-num); }
.tk-str { color: var(--tk-str); }
.tk-com { color: var(--tk-com); font-style: italic; }
.tk-def { color: var(--tk-def); font-weight: 600; }
.tk-val { color: var(--tk-val); font-weight: 600; }
.tk-proc { color: var(--tk-proc); font-weight: 600; }
.tk-name { color: var(--ink); }
.tk-br, .tk-op { color: var(--muted); }
.tk-err { text-decoration: underline wavy var(--danger); text-decoration-thickness: 1.5px; text-underline-offset: 3px; background: rgb(179 50 31 / 0.16); border-radius: 2px; }

