.ex-card { display: flex; flex-direction: column; gap: 4px; width: 100%; height: 100%; padding: 8px; text-align: left; border: 1px solid var(--line-strong); border-radius: var(--r); background: var(--panel); color: inherit; font: inherit; cursor: pointer; transition: background-color 120ms ease-out, border-color 120ms ease-out; }
