cat > scripts/build.ts <<'EOF'
// Bundles the app into a self-contained static site in dist/.
// BASE_PATH (default "/") is the URL prefix the site is served from, e.g. BASE_PATH=/Logomocja/builds/x/.
// When it is not set, asset URLs are relative, so the folder works from any location.
import { cp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";

const root = join(import.meta.dir, "..");
const dist = join(root, "dist");

const raw = process.env.BASE_PATH;
let prefix = "./";
if (raw && raw !== "/") {
  prefix = "/" + raw.replace(/^\/+|\/+$/g, "") + "/";
} else if (raw === "/") {
  prefix = "/";
}

await rm(dist, { recursive: true, force: true });
await mkdir(dist, { recursive: true });

const result = await Bun.build({
  entrypoints: [join(root, "src/main.ts")],
  outdir: dist,
  naming: { entry: "app.[ext]", chunk: "chunk-[hash].[ext]", asset: "asset-[hash].[ext]" },
  minify: true,
  target: "browser",
  sourcemap: "none",
});
if (!result.success) {
  for (const log of result.logs) console.error(log);
  process.exit(1);
}

let html = await readFile(join(root, "index.html"), "utf8");
html = html.replaceAll('"./', `"${prefix}`);
await writeFile(join(dist, "index.html"), html);
await cp(join(root, "public"), dist, { recursive: true });

const files = result.outputs.map((o) => o.path.replace(dist + "/", ""));
console.log(`Built dist/ (${files.join(", ")}) with asset prefix "${prefix}"`);
EOF
cat > scripts/serve.ts <<'EOF'
// Serves dist/ for a quick local look: bun run build && bun run dev
import { join } from "node:path";

const dist = join(import.meta.dir, "..", "dist");
const port = Number(process.env.PORT ?? 4173);
const base = "/" + (process.env.BASE_PATH ?? "/").replace(/^\/+|\/+$/g, "");
const prefix = base === "/" ? "/" : base + "/";

Bun.serve({
  port,
  async fetch(req) {
    let path = new URL(req.url).pathname;
    if (!path.startsWith(prefix)) return new Response("Not found", { status: 404 });
    path = path.slice(prefix.length) || "index.html";
    if (path.endsWith("/")) path += "index.html";
    const file = Bun.file(join(dist, path));
    return (await file.exists()) ? new Response(file) : new Response("Not found", { status: 404 });
  },
});
console.log(`http://localhost:${port}${prefix}`);
EOF
