import { test, expect, describe, beforeEach } from "bun:test";
import { encodeShare } from "../src/core/share";
import { COMMAND_DOCS } from "../src/core/docs";
import { exampleById } from "../src/core/examples";

// The DOM tests need happy-dom (a dev dependency); without it they are skipped.
let Window: any = null;
try { Window = (await import("happy-dom")).Window; } catch { /* skipped */ }

class MemoryKV {
  data = new Map<string, string>();
  getItem(k: string) { return this.data.get(k) ?? null; }
  setItem(k: string, v: string) { this.data.set(k, v); }
  removeItem(k: string) { this.data.delete(k); }
}

const frames = () => new Promise((r) => setTimeout(r, 40));

function boot(kv = new MemoryKV(), hash = "") {
  const win = new Window({ url: "https://example.test/Logomocja/builds/x/" + hash });
  const g = globalThis as any;
  for (const k of ["window", "document", "location", "history", "navigator", "HTMLElement", "HTMLCanvasElement", "Node", "Event", "KeyboardEvent"]) {
    g[k] = k === "window" ? win : win[k] ?? g[k];
  }
  g.requestAnimationFrame = (cb: FrameRequestCallback) => setTimeout(() => cb(performance.now()), 5);
  g.cancelAnimationFrame = (h: number) => clearTimeout(h);
  g.ResizeObserver = class { observe() {} disconnect() {} };
  g.CSS = { escape: (s: string) => s };
  win.matchMedia = () => ({ matches: false, addEventListener() {} });
  const noop = new Proxy(function () {}, { get: () => noop, apply: () => noop, set: () => true }) as any;
  win.HTMLCanvasElement.prototype.getContext = function (type: string) { return type === "2d" ? noop : null; };
  win.HTMLCanvasElement.prototype.toBlob = function (cb: (b: Blob) => void) { cb(new Blob(["png"], { type: "image/png" })); };
  win.document.body.innerHTML = '<div id="app"></div>';
  return { win, kv };
}

async function mount(kv = new MemoryKV(), hash = "") {
  const env = boot(kv, hash);
  const { createApp } = await import("../src/ui/app?" + Math.random());
  const api = createApp(env.win.document.getElementById("app")!, kv);
  await frames();
  return { ...env, api, doc: env.win.document as Document, q: (s: string) => env.win.document.querySelector(s) as HTMLElement | null };
}

const d = Window ? describe : describe.skip;

d("app: hook and editor integration", () => {
  test("window-level hook exposes version, run and open", async () => {
    const { api } = await mount();
    expect(typeof api.version).toBe("string");
    expect(api.run("np 10", "2d").segments).toHaveLength(1);
  });

  test("open() puts the program in the editor, draws it, and resolves with the result", async () => {
    const { api, q, kv } = await mount();
    const r = await api.open("kolor \"#c1763d\"\npowtorz 4 [np 50 pw 90]", "2d");
    expect(r.error).toBeNull();
    expect(r.segments).toHaveLength(4);
    expect((q(".ed-ta") as HTMLTextAreaElement).value).toContain("powtorz 4");
    expect(q(".status-text")!.textContent).toContain("Koniec programu. 4 odcinki");
    expect(kv.getItem("logomocja:v1:draft:2d")).toContain("powtorz 4");
  });

  test("open() with a parse error draws nothing and marks the error in the editor", async () => {
    const { api, q } = await mount();
    const r = await api.open("np 10\nnp 10 -5", "2d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 7 });
    const problem = q(".problem")!;
    expect(problem.hidden).toBe(false);
    expect(problem.textContent).toContain("Wiersz 2, kolumna 7");
    expect(q(".ed-under .tk-err")).not.toBeNull();
    expect(q(".gn.is-error")!.textContent).toBe("2");
  });

  test("open() in 3D works and repeated opens do not accumulate drawings", async () => {
    const { api, q } = await mount();
    await api.open("gora 90 np 10", "3d");
    const r = await api.open("np 5", "3d");
    expect(r.segments).toHaveLength(1);
    expect(q(".status-text")!.textContent).toContain("1 odcinek");
    expect((q('input[name="tryb"][value="3d"]') as HTMLInputElement).checked).toBe(true);
  });

  test("without WebGL the 3D mode says why and still shows the program's result", async () => {
    const { api, q } = await mount();
    await api.open("gora 90 np 10", "3d");
    const notice = q(".gl-notice")!;
    expect(notice.hidden).toBe(false);
    expect(notice.textContent).toContain("Widok 3D jest wyłączony");
    expect(notice.textContent).toContain("WebGL");
    await api.open("np 10", "2d");
    expect(q(".gl-notice")!.hidden).toBe(true);
  });
});

d("app: execution controls", () => {
  test("step highlights the executed line, pause is only available while running, reset clears", async () => {
    const { q, doc } = await mount();
    const btn = (label: string) => [...doc.querySelectorAll<HTMLButtonElement>(".runbar .btn")].find((b) => b.textContent!.includes(label))!;
    expect(btn("Pauza").disabled).toBe(true);
    btn("Krok").click();
    expect(q(".ed-under .ln.is-active")).not.toBeNull();
    expect(q(".bench")!.dataset.state).toBe("paused");
    expect(btn("Pauza").disabled).toBe(false);
    expect(btn("Wznów")).toBeDefined();
    btn("Reset").click();
    expect(q(".bench")!.dataset.state).toBe("idle");
    expect(q(".ed-under .ln.is-active")).toBeNull();
  });

  test("editing while stepping flags the drawing as outdated", async () => {
    const { q, doc, win } = await mount();
    [...doc.querySelectorAll<HTMLButtonElement>(".runbar .btn")].find((b) => b.textContent!.includes("Krok"))!.click();
    const ta = q(".ed-ta") as HTMLTextAreaElement;
    ta.value = "np 3";
    ta.dispatchEvent(new win.Event("input", { bubbles: true }));
    expect(q(".status-text")!.textContent).toContain("Program zmieniony");
  });

  test("Ctrl+Enter runs the program; the shortcut list is reachable from the header", async () => {
    const { q, doc, win } = await mount();
    doc.dispatchEvent(new win.KeyboardEvent("keydown", { key: "Enter", ctrlKey: true, bubbles: true }));
    expect(q(".bench")!.dataset.state).toBe("running");
    (doc.querySelector('[aria-label="Skróty klawiszowe"]') as HTMLButtonElement).click();
    expect(doc.querySelector("dialog")!.textContent).toContain("Ctrl + Enter");
  });
});

d("app: examples, drafts, sharing", () => {
  const openExamples = (doc: Document) => [...doc.querySelectorAll<HTMLButtonElement>("button")].find((b) => b.textContent!.includes("Przykłady"))!.click();

  test("all thirteen examples are listed and load into the right mode", async () => {
    const { doc, q } = await mount();
    openExamples(doc);
    expect(doc.querySelectorAll(".ex-card")).toHaveLength(13);
    (doc.querySelector('[data-example="kula"]') as HTMLButtonElement).click();
    expect((q(".ed-ta") as HTMLTextAreaElement).value).toBe(exampleById("kula")!.code);
    expect((q('input[name="tryb"][value="3d"]') as HTMLInputElement).checked).toBe(true);
    expect(doc.querySelector("dialog")).toBeNull();
  });

  test("loading an example over a modified draft keeps the draft and offers undo", async () => {
    const { api, doc, q } = await mount();
    await api.open("np 77", "2d");
    openExamples(doc);
    (doc.querySelector('[data-example="gwiazda"]') as HTMLButtonElement).click();
    const toast = q(".toast")!;
    expect(toast.textContent).toContain("Poprzedni szkic zachowano");
    expect((q(".ed-ta") as HTMLTextAreaElement).value).toBe(exampleById("gwiazda")!.code);
    [...toast.querySelectorAll("button")].find((b) => b.textContent === "Cofnij")!.click();
    expect((q(".ed-ta") as HTMLTextAreaElement).value).toBe("np 77");
  });

  test("a permalink loads and runs the program, then clears itself from the address", async () => {
    const { q, win } = await mount(new MemoryKV(), encodeShare("powtorz 3 [np 30 pw 120]", "2d"));
    await frames();
    expect((q(".ed-ta") as HTMLTextAreaElement).value).toBe("powtorz 3 [np 30 pw 120]");
    expect(q(".status-text")!.textContent).toContain("Koniec programu. 3 odcinki");
    expect(win.location.hash).toBe("#/pracownia");
  });

  test("the draft of each mode survives a reload", async () => {
    const kv = new MemoryKV();
    const a = await mount(kv);
    await a.api.open("np 11", "2d");
    await a.api.open("gora 5 np 12", "3d");
    const b = await mount(kv);
    expect((b.q(".ed-ta") as HTMLTextAreaElement).value).toBe("gora 5 np 12");
    (b.q('input[name="tryb"][value="2d"]') as HTMLInputElement).click();
    (b.q('input[name="tryb"][value="2d"]') as HTMLInputElement).dispatchEvent(new b.win.Event("change", { bubbles: true }));
    expect((b.q(".ed-ta") as HTMLTextAreaElement).value).toBe("np 11");
  });

  test("theme button cycles automatic, light, dark and remembers the choice", async () => {
    const kv = new MemoryKV();
    const { doc, win } = await mount(kv);
    const btn = [...doc.querySelectorAll<HTMLButtonElement>("button")].find((b) => b.textContent!.includes("Motyw"))!;
    btn.click();
    expect(doc.documentElement.dataset.theme).toBe("light");
    btn.click();
    expect(doc.documentElement.dataset.theme).toBe("dark");
    expect(kv.getItem("logomocja:v1:theme")).toBe("dark");
    btn.click();
    expect(doc.documentElement.dataset.theme).toBeUndefined();
    void win;
  });
});

d("app: challenges and reference", () => {
  test("a challenge is checked automatically, the result is shown and progress survives a reload", async () => {
    const kv = new MemoryKV();
    const a = await mount(kv, "#/wyzwania/kwadrat");
    expect(a.q(".ch-task")!.textContent).toContain("kwadrat");
    const ta = a.q(".ed-ta") as HTMLTextAreaElement;
    ta.value = "powtorz 4 [np 80 pw 90]";
    ta.dispatchEvent(new a.win.Event("input", { bubbles: true }));
    [...a.doc.querySelectorAll<HTMLButtonElement>("button")].find((b) => b.textContent!.includes("Sprawdź"))!.click();
    expect(a.q(".result")!.className).toContain("is-fail");
    expect(a.q(".result")!.textContent).toMatch(/Brakuje/);
    ta.value = "powtorz 4 [np 100 pw 90]";
    ta.dispatchEvent(new a.win.Event("input", { bubbles: true }));
    [...a.doc.querySelectorAll<HTMLButtonElement>("button")].find((b) => b.textContent!.includes("Sprawdź"))!.click();
    expect(a.q(".result")!.className).toContain("is-pass");
    expect(a.q(".ch-summary")!.textContent).toContain("Rozwiązane: 1 z");
    const b = await mount(kv, "#/wyzwania/kwadrat");
    expect(b.q(".ch-summary")!.textContent).toContain("Rozwiązane: 1 z");
    expect(b.q(".badge-ok")).not.toBeNull();
  });

  test("the reference documents every command with an example and can open one in the studio", async () => {
    const { doc, q } = await mount(new MemoryKV(), "#/polecenia");
    expect(doc.querySelectorAll(".cmd")).toHaveLength(COMMAND_DOCS.length);
    expect(doc.querySelectorAll(".cmd pre.code")).toHaveLength(COMMAND_DOCS.length);
    const first = doc.querySelector(".cmd .btn") as HTMLButtonElement;
    first.click();
    expect((q(".ed-ta") as HTMLTextAreaElement).value).toBe(COMMAND_DOCS[0].example.code);
    expect(doc.body.dataset.route).toBe("pracownia");
  });
});
