cat > tests/camera.test.ts <<'EOF'
import { test, expect } from "bun:test";
import { cameraEye, lookAt, mul, perspective, projectToScreen } from "../src/ui/view3d";

const W = 800, H = 600;
const screen = (p: [number, number, number], yaw: number, pitch: number, dist = 300) => {
  const eye = cameraEye([0, 0, 0], yaw, pitch, dist);
  const view = lookAt(eye, [0, 0, 0], [0, 0, 1]);
  const proj = perspective((45 * Math.PI) / 180, W / H, 1, 5000);
  return projectToScreen(mul(proj, view), p, W, H);
};

test("looking along +Y from the front: +X is to the right, +Z is up, the origin is centred", () => {
  const [ox, oy] = screen([0, 0, 0], 0, 0);
  expect(ox).toBeCloseTo(W / 2, 3);
  expect(oy).toBeCloseTo(H / 2, 3);
  const [rx] = screen([50, 0, 0], 0, 0);
  expect(rx).toBeGreaterThan(W / 2 + 10);
  const [, uy] = screen([0, 0, 50], 0, 0);
  expect(uy).toBeLessThan(H / 2 - 10); // screen y grows downwards
});

test("from above the sheet looks like the 2D plane: +Y points up the screen", () => {
  const [, fy] = screen([0, 50, 0], 0, 1.4);
  expect(fy).toBeLessThan(H / 2 - 5);
  const [fx] = screen([50, 0, 0], 0, 1.4);
  expect(fx).toBeGreaterThan(W / 2 + 10);
});

test("points behind the camera are reported as not visible", () => {
  const eye = cameraEye([0, 0, 0], 0, 0, 100);
  expect(eye[1]).toBeCloseTo(-100, 6);
  const [, , visible] = screen([0, -500, 0], 0, 0, 100);
  expect(visible).toBe(false);
});

test("orbiting by a positive yaw moves the camera towards +X", () => {
  expect(cameraEye([0, 0, 0], 0.5, 0, 100)[0]).toBeGreaterThan(40);
});
EOF
