describe("run: lexical robustness", () => {
  test("a byte-order mark, no-break spaces and CRLF line endings are plain whitespace", () => {
    const r = run("﻿np 5\r\npw 90\r\nnp 5\r\n", "2d");
    expect(r.error).toBeNull();
    expect(r.segments).toHaveLength(2);
  });
  test("columns count characters, not UTF-16 units", () => {
    expect(run("; 😀\nnp 😀", "2d").error).toMatchObject({ line: 2, column: 4 });
  });
  test("an unknown character is reported where it stands", () => {
    expect(run("np 5 @", "2d").error).toMatchObject({ line: 1, column: 6 });
    expect(run("np #5", "2d").error).toMatchObject({ line: 1, column: 4 });
  });
});
